(window.PF_CAT_SHARD=window.PF_CAT_SHARD||{})["76457"]={"3035":{"i":"3035","entryRequirements":"Bachelor's degree or equivalent experience, and relevant practice in a related professional field   \n\r\n(International: IELTS 6.5 Academic, with no band below 6.0, or equivalent)","strategicPurposeStatement":"The Postgraduate Diploma in Professional Practice provides graduates who apply advanced research knowledge and scholarship to their professional practice context. It is designed for professionals seeking to advance their knowledge and skills. Graduates have built on their professional experience to gain internationally recognised knowledge and skills for career enhancement, capable to lead practice at an advanced, specialised level. Graduates have the capability to work effectively in interprofessional teams for the provision of high-quality services to diverse people and communities","graduateProfile":"The graduate will: 1. Demonstrate advanced professional knowledge and practice. 2. Have advanced understanding of contemporary professional practice and service delivery issues. 3. Critically evaluate practice development trends, issues and extant solutions. 4. Evaluate strategic policy priorities as they apply to professional practice. 5. Critically evaluate and apply research and evidence for best professional practice outcomes in the professional context. 6. Have leadership skills able to be applied in inter-professional contexts. 7. Critically analyse and integrate best practice principles in professional practice when working with diverse people and communities.","educationPathway":"Graduates of the Postgraduate Diploma in Professional Practice may apply to enrol in the Master of Professional Practice programme or any other Master programmes in New Zealand or overseas as they will meet Level 8 requirements. Students enrolling in this programme may build on previous successful and related study such as a postgraduate certificate or equivalent level 8 qualification.","developedBy":"New Zealand Institute of Skills and Technology","qualityAssuredBy":"New Zealand Qualifications Authority","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=3035"},"3036":{"i":"3036","entryRequirements":"Bachelor's degree or equivalent experience, and relevant practice in a related professional field   \n\r\n(International: IELTS 6.5 Academic, with no band below 6.0, or equivalent)","strategicPurposeStatement":"The Postgraduate Certificate in Professional Practice provides graduates who will contribute advanced knowledge and scholarship. It is designed for professionals seeking to advance their knowledge and skills. Graduates have built on their professional experience to gain  \n\r\ninternationally recognised knowledge and skills for career enhancement for practice at an advanced, specialised level. Graduates have the capability to work effectively in interprofessional teams for the provision of high-quality services to diverse people and communities.","graduateProfile":"The graduate will: 1. Demonstrate a critical understanding of key principles of professional knowledge and practice 2. Have critical understanding of how contemporary professional practice impacts on service users 3. Articulate practice development issues in the context of own professional practice and discipline 4. Critically appraise the strategic policies that impact on professional practice 5. Extend knowledge of leadership skills for interprofessional practice 6. Critically analyse best practice principles in professional practice when working with diverse people and communities","educationPathway":"Graduates of the Postgraduate Certificate in Professional Practice may apply to enrol in the Postgraduate Diploma in Professional Practice, or the Master of Professional Practice programme or any other Master programmes in New Zealand or overseas. Students enrolling in this programme may build on previous successful and related study such as a postgraduate certificate or equivalent level 8 qualifications","developedBy":"New Zealand Institute of Skills and Technology","qualityAssuredBy":"New Zealand Qualifications Authority","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=3036"},"3098":{"i":"3098","entryRequirements":"Academic requirement  \n\n\n\r\nAll students will initially enrol in the BSW. At the discretion of the Head of School students who achieve a B+ average over all Level 7 core compulsory social work courses in the third year may be offered entry to the Bachelor of Social Work (Honours) for their fourth year of study. Should they choose to undertake study at Honours level, they will be enrolled into the BSW (Honours) programme, and the credits gained in the first three years of BSW study will be credited to the BSW (Honours).  \n\r\nHealth and professional requirement  \n\r\nALL applicants are required to provide a completed POLICE VETTING REQUEST AND CONSENT Form and a PERSONAL DECLARATION Form (see Appendices 1 and 2) annually.","strategicPurposeStatement":"The BSW (Hons) will enable students to become competent, critical, reflective social workers with personal attributes and an advanced level of critical and analytical ability to underpin their practice. They will be able to plan and conduct research in social work. They will also have the educational requirements for NZ registration and be equipped to proceed to advanced study in the subject.","graduateProfile":"The objective of this programme is to produce graduates that: \n\n\n\r\n1. Are empathic, non-judgmental, respectful, resilient and self-aware; and demonstrate integrity, authenticity and professionalism  \n\r\n2. Take an analytical and critically reflective approach to social work practice that includes the use of supervision, continuing professional development, on-going learning and personal wellbeing  \n\r\n3. Use analysis of institutional and societal structures that oppress, to inform social work practice  \n\r\n4. Are able to work collaboratively and in partnership with individuals and groups from diverse backgrounds  \n\r\n5. Integrate understanding of the significance and implications of Te Tiriti o Waitangi and te ao Māori into social work practice  \n\r\n6. Work in accordance with the Aotearoa New Zealand Association of Social Workers (ANZASW) Code of Ethics and the SWRB Code of Conduct  \n\r\n7. Have an extensive knowledge base, skills and professional attributes to work across a range of diverse social work contexts and communities  \n\r\n8. Are proficient in professional literacies, including academic and research literacy, information literacy, numeracy, and digital literacy  \n\r\n9. Are able to undertake ethical research, critically reflect on the process, analyse the outcomes and evaluate their relevance to social work  \n\r\n10. Utilise research in an analytical and critically reflective manner to inform practice","educationPathway":"The programme will prepare learners to be lifelong learners and to take responsibility for their own learning and professional development. They will be able to undertake post-graduate Masters level programmes in the field of social work as well as in related fields.","developedBy":"Eastern Institute of Technology","qualityAssuredBy":"New Zealand Qualifications Authority","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=3098"},"3370":{"i":"3370","entryRequirements":"Entry Requirements: Students must: * Be able to access a relevant workplace; and * Have a Bachelor or Bachelor Honours degree in a cognate subject with a B average or above; or * Have a Postgraduate Certificate or Postgraduate Diploma in a cognate subject with a B average or above; or * In exceptional circumstances, based on academic merit and relevant experience, students who do not meet the academic and practical or professional experience requirements above may be considered for admission subject to the completion of any qualifying courses the Postgraduate Board of Studies may prescribe which must be completed either prior to or concurrently; and have * IELTS Academic 6.5 with no band score lower than 6.0, or equivalent or Waiariki English Test 65 with no score lower than 60 for Mentoring and Leadership and Adult Teaching endorsements; or * IELTS Academic 7.0 with no band score lower than 7.0, or equivalent or Waiariki English Test 70 with no score lower than 70 for Vulnerable Peoples, and Infection Prevention and Control endorsements.","strategicPurposeStatement":"The Master of Applied Professional Studies programme aims to provide a flexible range of study options that enable learners to match their needs to the qualification they are seeking to gain and to extend their domain of practice within a chosen professional field. The programme aims to integrate theory with practice within interrogative environments that support learners to broaden their knowledge and experience through: * Reflective practice * Critical evaluation * In-depth analysis of critical social, cultural and professional practice issues * Applied professional practice research * Synthesis and construction of new and/or innovative professional practice initiatives and/or applications * Articulation of personalised professional practice model(s) along with the theories, cultural understandings and experiences that inform the model(s)","graduateProfile":"Upon successful completion of the Master of Applied Professional Studies, graduates will be able to: * Perform as critically reflective and interdisciplinary practitioners; * Demonstrate leadership in their field of study nationally and internationally; * Analyse and synthesise information; * Use and apply knowledge to address novel or new problems and issues; * Develop and implement appropriate research methodologies; and * Exhibit higher level knowledge and understanding of their profession through cognitive, practical, personal and enabling skills.","educationPathway":"The Master of Applied Professional Studies is specifically aimed to prepare graduates for leadership \n\r\nroles and becoming advanced practitioners in their relevant field of study.","developedBy":"Toi Ohomai Institute of Technology","qualityAssuredBy":"New Zealand Qualifications Authority","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=3370"},"3933":{"i":"3933","entryRequirements":"Applicants must have: A Bachelor's Degree or a Graduate Certificate or Diploma in a similar subject or relevant skills and knowledge acquired through appropriate work or professional experience. Applicants who are unable to evidence that they meet Academic entry requirements, but who can demonstrate acquired skills for tertiary study gained through study, work and/or life experience in a similar area, may be approved for alternative entry by the Curriculum Manager (or delegate). If English is not the applicant's first language, applicants will need to provide evidence from: An International English Language Testing System (IELTS) overall academic score of at least 7.0 (with at least 7.0 in each band) from a single test issued within the last two years OR A test or qualification on the acceptable alternatives English Proficiency Outcomes Table OR Achieved NCEA Level 3 University Entrance requirements. If English is not the applicant's first language, applicants will need to provide evidence from: An International English Language Testing System (IELTS) overall academic score of at least 7.0 (with at least 7.0 in each band) from a single test issued within the last two years OR A test or qualification on the acceptable alternatives English Proficiency Outcomes Table OR Achieved NCEA Level 3 University Entrance requirements. Applicants are required to: ? Provide evidence of a minimum of two years post qualifying experience in their professional field of practice (or the equivalent as approved by the Curriculum Manager). ? Supply the names and contact details of two professional referees.","strategicPurposeStatement":"This Programme is underpinned by a student-centred philosophy of adult learning with a core valuing of transformative learning. This value underpins all components of the programme - assessment processes, course delivery, experiential and interactive teaching delivery styles, lecturer-student interactions, skill development and theory to practice integration. This philosophy fosters relationships and environments that nurture the development of health and social services scholarship and wisdom for practice. NMIT supports the belief that the best learning opportunities for students in postgraduate study are those which: Are flexible, responsive and always in the direction of the student as an independent learner Are informed by respect and care Challenge students and academic staff members to view the world in different ways to expand their vision Give students the tools to develop/enhance a professional identity which is earned, ethical and values difference Teaching and learning at the postgraduate level recognises students as adult learners and colleagues. It is understood that knowledge is something that is created dialogically. NMIT provides an environment where lecturers and students engage with each other and students enrich their learning through opportunities to share ideas and experiences with each other as groups of inter-disciplinary practitioners. The delivery promotes reflective learning in relation to shared experiences and motivates students to develop enthusiasm for interdependent and independent study.","graduateProfile":"This programme will appeal to learners wishing to become a professional supervisor to others in their profession or to enhance their skills in a management position in any professional field. It is designed to extend and deepen professional knowledge and skills in the fields of health, education, social practice and management.","educationPathway":"Further studies in the area of supervision.","developedBy":"Nelson Marlborough Institute of Technology (NMIT)","qualityAssuredBy":"New Zealand Qualifications Authority","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=3933"},"4883":{"i":"4883","entryRequirements":"Completed a relevant Bachelors Honours degree with a minimum GPA or a relevant Bachelors Honours degree and passed 60 points towards the Postgraduate Certificate in Intellectual Property or a relevant Bachelors Honours degree with a minimum GPA and relevant professional experience, or a Bachelor of Laws or or Bachelor of Laws (Honours) with a minimum GPA.","strategicPurposeStatement":"Master of Intellectual Property graduates will have attained the knowledge, values and skills related to intellectual property law that will help enable them to practice as a patent attorney.","developedBy":"University of Auckland","qualityAssuredBy":"New Zealand Qualifications Authority","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=4883"},"AU5515":{"i":"AU5515","entryRequirements":"A Bachelors degree in a relevant subject with a minimum GPA. An interview supported by references and evidence of suitability is normally required. Applicants must undergo a police check to meet the requirements of the Social Workers Registration Act 2003 and safety checks required by the Children's Act 2014.","strategicPurposeStatement":"Graduates of the Master of Social Work (Professional) programme will know and understand the values, theories and interventions that underpin social work practice. They will be critical, reflective practitioners able to contribute to statutory and community social services and pursue personal professional goals and postgraduate study.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5515"},"VI005D":{"i":"VI005D","entryRequirements":"The entry requirements the MAppLing are a Bachelor's degree (or equivalent qualification) with a grade average of B or better in Linguistics, English Language, Education or a language other than English (or another relevant degree), and at least two years of professional experience in language education or another area of applied linguistics or a related field. Applicants without relevant experience will be considered on a case-by-case basis and may be expected to complete bridging courses depending on the nature and extent of their previous experience and qualifications.","strategicPurposeStatement":"Graduates of the MAppLing programme will demonstrate advanced knowledge of a range of core topics in applied linguistics. They will be able to engage critically and creatively with research in applied linguistics and apply this knowledge to understanding and addressing language-related real-life problems. The programme develops in students high-level transferable skills for language-related fields, such as language education policy and planning, and prepares students for entry into PhD programmes in New Zealand or internationally.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI005D"},"WI0252":{"i":"WI0252","entryRequirements":"Bachelor of Laws or equivalent","strategicPurposeStatement":"Graduates will have an understanding of Pacific legal thought and practice and the skills to participate actively in the development of Pacific jurisprudence to enhance global understanding of Pacific legal systems.","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0252"},"CN0106":{"i":"CN0106","entryRequirements":"Bachelor's degree including specified prerequisites, or Bachelor of Arts with Honours in the subject to be taken for Master of Arts.","strategicPurposeStatement":"Graduates will be able to build on the attributes of their entry qualifications and develop a substantial piece of supervised research that demonstrates advanced analytic, scholarly and research skills. They will extend their range of career opportunities while also preparing the way for higher study and research.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0106"},"VI002R":{"i":"VI002R","entryRequirements":"A bachelor's degree or equivalent, completed with a B grade average or higher.","strategicPurposeStatement":"Graduates will have detailed knowledge of the role of trade in society and its legal rules and economic rationales, and a keen awareness of the social, economic, political and cultural context in which international trade operates.  They will have an appreciation of the nature and contribution of different perspectives on international trade and related theories, including the customary laws of Maori and Pacific peoples. Using a multidisciplinary perspective, graduates will be able to analyse problems, contribute to relevant policy discussion and provide solutions.  Graduates should find work or enhance their employment prospects in relevant areas of government or business. Graduates may be able to progress to doctoral studies.","graduateProfile":"NA","educationPathway":"NA","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI002R"},"MY0020":{"i":"MY0020","entryRequirements":"Bachelor of Arts or equivalent.","strategicPurposeStatement":"Graduates will have developed and advanced the knowledge and skills attained in their undergraduate degree, and acquired independent research skills.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0020"},"OO0546":{"i":"OO0546","entryRequirements":"Entry requirements will be a BA majoring in Archaeology,  Anthropology, or related discipline, or an undergraduate degree in another discipline  but with relevant professional experience, and a B+ average across relevant 300-level papers.","strategicPurposeStatement":"Graduates of this programme will have a comprehensive understanding of issues and debates in heritage studies and archaeological heritage management","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0546"},"WI0137":{"i":"WI0137","entryRequirements":"A New Zealand university entrance qualification or equivalent.","strategicPurposeStatement":"Graduates will have knowledge and skills from both law and science disciplines","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0137"},"AU5766":{"i":"AU5766","entryRequirements":"Three years relevant professional experience, and either completed a relevant Bachelors degree or equivalent with a minimum GPA, or passed 60 points in the Postgraduate Certificate in Professional Supervision or Psotgraduate Diploma in Professional Supervision with a minimum GPA. Must be currently employed or volunteering in an appropriate professional context.","strategicPurposeStatement":"MProfSupPrac graduates will have mastery of clinical skills in professional supervision as well as advanced specialist knowledge of the field. They will have a demonstrated ability to apply specialist knowledge to practice in diverse clinical settings in culturally sustaining ways.","graduateProfile":"Written assignments, individual and group projects, case analyses, and presentations.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5766"},"AK1075":{"i":"AK1075","entryRequirements":"A relevant bachelor's degree.","strategicPurposeStatement":"PgDipENMS graduates will have advanced knowledge and understanding of new media practices in relation to a specified field of English Studies. They will be able to engage in research in the area, taking an analytical, critical and reflective approach and be prepared for further postgraduate study.","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1075"},"MY0172":{"i":"MY0172","entryRequirements":"Admission to the Postgraduate Diploma in Social Work is on the basis of a completed Social Work degree.","strategicPurposeStatement":"Following completion of this course, students will demonstrate ability to:  · Extend existing bodies of knowledge in an area specific to social work through intellectual independence, analytic rigour and critical evaluation.   · Master theoretical issues and research methods related to social work  and critically analyse bodies of knowledge in social work and apply this knowledge to their own contexts.   · critically read and appraise research in social work published in peer-reviewed social work and related journals.   · apply knowledge of current theories of social service practice through the development of skills that allow the pursuit of scholarly interest in specific fields of social work practice.   · apply knowledge of methodological and theoretical issues that relate to cultural competence as it relates to research and practice principles with Maori and other diverse cultural groups.   · Provide leadership in specific areas of social work practice through the dissemination of information in workplace and through clinical supervision and mentoring of students and beginning practitioners.  Graduates who achieve the qualification with merit or higher may be eligible for admission to the Master of Social Work degree   Graduates will already be employed as social workers. This postgraduate diploma aids their professional development as advanced practitioners and specialists in particular fields of practice and may enhance their career progression.","graduateProfile":"Following completion of this course, students will demonstrate ability to:  · Extend existing bodies of knowledge in an area specific to social work through intellectual independence, analytic rigour and critical evaluation.   · Master theoretical issues and research methods related to social work  and critically analyse bodies of knowledge in social work and apply this knowledge to their own contexts.   · critically read and appraise research in social work published in peer-reviewed social work and related journals.   · apply knowledge of current theories of social service practice through the development of skills that allow the pursuit of scholarly interest in specific fields of social work practice.   · apply knowledge of methodological and theoretical issues that relate to cultural competence as it relates to research and practice principles with Maori and other diverse cultural groups.   · Provide leadership in specific areas of social work practice through the dissemination of information in workplace and through clinical supervision and mentoring of students and beginning practitioners.  Graduates who achieve the qualification with merit or higher may be eligible for admission to the Master of Social Work degree   Graduates will already be employed as social workers. This postgraduate diploma aids their professional development as advanced practitioners and specialists in particular fields of practice and may enhance their career progression.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0172"},"AU0026":{"i":"AU0026","entryRequirements":"A New Zealand university entrance qualification or an approved alternative. Must meet entry requirements of each component degree. Selection criteria apply.","strategicPurposeStatement":"BCom/LLB(Hons) graduates will demonstrate knowledge and understanding of the content and application of elements of both Commerce and Law disciplines with additional enhanced research and writing skills within the law component.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU0026"},"WI0156":{"i":"WI0156","entryRequirements":"Bachelor of Sport & Leisure Studies with Honours or Postgraduate Diploma in Sport and Leisure Studies or equivalent.","strategicPurposeStatement":"This 2 year version of the MSpLS programme is no longer offered. The University now offers a 1 year MSpLS building on a BLS(Hons) degree. Please refer to the University of Waikato website for further details & other options. \nhere","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0156"},"CN0197":{"i":"CN0197","entryRequirements":"Applicants need to have a Bachelor's degree with a major or equivalent in Maori and Indigenous Studies or Te Reo Maori or a related subject.","strategicPurposeStatement":"Graduates will have developed an advanced understanding of Maori cultural practices, oral traditions and contemporary social phenomenon in Maori and indigenous societies. They will also have engaged in the critical reading of academic material in the discipline, acquired the advanced skills for research in this area and engaged in an original piece of research.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0197"},"AU5176":{"i":"AU5176","entryRequirements":"A bachelors degree, current employment in a health counselling, social or human services or other appropriate professional context, and at least two years relevant professional experience.","strategicPurposeStatement":"PGCertProfSup graduates will know and understand the principles, concepts and ideas that define professional supervision and inform supervision practice.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5176"},"VI001T":{"i":"VI001T","strategicPurposeStatement":"Graduates will have advanced knowledge and understanding of aspects of the political science discipline, including theoretical issues. They will be able to evaluate and analyse findings and discussions in the political science literature, conceptualise problems in political analysis and political practice and be able to conduct small-scale, independent research on topics in political science. Graduates will be qualified for careers in public affairs including politics, the civil service, think tanks, lobbying and civil society organisations. Some graduates may be able to continue to the Master of Political Science (MPols, VI001S) or a research-based masters degree. The PGDipPols also acts as a step-off qualification for students unable to complete the MPols.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI001T"},"AU5140":{"i":"AU5140","entryRequirements":"A New Zealand university entrance qualification or an approved alternative. Must meet entry requirements of each component degree. Selection criteria apply.","strategicPurposeStatement":"BE(Hons)/LLB graduates will demonstrate knowledge and understanding of the content and application of elements of both Engineering and Law disciplines.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5140"},"AU4013":{"i":"AU4013","strategicPurposeStatement":"PGDipClinPsych graduates will have the theoretical and practical skills to enable them to register and practise in the field of clinical psychology","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU4013"},"MY0256":{"i":"MY0256","entryRequirements":"The Postgraduate Diploma is available to students entering from the Bachelors degree who do not have the appropriate grade average for entry to the Honours or Masters programme, or who do not wish to commit to the Masters programme, or who wish to pursue a taught qualification for workplace advancement, and who have completed a Bachelor of Sport and Exercise or equivalent sport-related degree with at least an overall B- grade average.","strategicPurposeStatement":"Graduates will build on the interdisciplinary approach to the study of sport and exercise to a higher level than a BSpEx graduate. They will have the specialised knowledge and practical skills of their majoring area: sport management, sport coaching, exercise science, exercise prescription and training, or physical education. More generically, they can critically evaluate and apply theories in diverse sport and exercise contexts, particularly those that encourage cross-disciplinary and inter-sectoral collaboration. They will have a good grasp of the key underlying principles of the several facets of sport and exercise and be able to implement and adapt these principles within a rapidly-changing professional environment.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0256"},"VI00N9":{"i":"VI00N9","entryRequirements":"Completed a Bachelor's degree in a relevant area with at least a B grade average in 60 points of 300-level courses in the majoring subject or relevant area of study (or extensive practical, professional, or scholarly experience that provides an equivalent level of preparation); and been accepted by the Head of School as capable of proceeding with the proposed course of study.","strategicPurposeStatement":"Graduates will have gained an advanced understanding of strategic analysis, security issues and related areas.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI00N9"},"OO0071":{"i":"OO0071","entryRequirements":"A Bachelor of Theology degree with an average grade of at least B+ in the final year of study; or equivalent.","strategicPurposeStatement":"This Honours degree provides in-depth knowledge, plus an introduction to research, in a chosen theological area. It also allows a range of optional papers. Graduates are able to pursue personal professional goals and postgraduate study.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0071"},"LI6591":{"i":"LI6591","entryRequirements":"Entry is by completion of an undergraduate degree in a related area of study with a B average at 300 level. If students perform well in the Postgraduate Diploma in Land and Society, then they will be equipped to continue to study at the Masters or even PhD level.","strategicPurposeStatement":"Graduates of this programme will have developed an advanced, multi-disciplinary appreciation of the theory and methods for understanding the interaction of people, societies and their physical and natural environments. They will also have gained comprehensive skills in applying that theory to significant 'real world' problems. Graduates of the Postgraduate Diploma in Land and Society will be able to contribute to knowledge regarding socio-physical phenomena, critically evaluate information, and communicate this knowledge effectively. They will have quantitative or qualitative analytic skills, or both, that will allow them to solve a range of both theoretical and practical problems. Graduates will be equipped with advanced research skills and capable of high-level research.","developedBy":"Lincoln University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=LI6591"},"CN0126":{"i":"CN0126","entryRequirements":"Bachelor of Social Work with Honours from a New Zealand university; or a bachelor's degree plus a graduate diploma in social work with a B+ average or better; or completion of a prescribed qualifying course.","strategicPurposeStatement":"Graduates will have developed research skills and the ability to undertake independent study. They will be equipped to demonstrate social work practice to an international standard.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0126"},"AU5527":{"i":"AU5527","entryRequirements":"BSc or BA with a major in Psychology (or equivalent) with an average grade in the final year of study that is equivalent to a B or higher.","strategicPurposeStatement":"MHealthPsych graduates will be eligible to apply for the PGDipHealthPsych, which gives specific training in clinical health psychology and provides a route to Registered Psychologist status.  Alternatively graduates can pursue research and health promotion careers within hospital, private, or university environments.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5527"},"LI0255":{"i":"LI0255","entryRequirements":"A relevant bachelors degree with appropriate grades","strategicPurposeStatement":"Graduates will be able to apply a multi- and interdisciplinary approach to the central theoretical, methodological and substantive topic areas of social science.","developedBy":"Lincoln University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=LI0255"},"AU5181":{"i":"AU5181","entryRequirements":"An average grade of B or higher in either a four-year bachelors degree, or a bachelors (honours) degree, or a bachelors degree and a professional or postgraduate qualification equivalent to one years advanced study.","strategicPurposeStatement":"MLS graduates will have an enhanced understanding of legal concepts and legal methodology, the ability to apply legal research at an advanced level and to apply the law in a variety of social, environmental, cultural and commercial contexts.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5181"},"OO0500":{"i":"OO0500","entryRequirements":"A Bachelor of Laws or Bachelor of Laws with Honours degree, or equivalent.","strategicPurposeStatement":"Graduates of this degree programme will be able to: 1. Write a legal opinion on an area of law that identifies the basis for the criticism, evaluates arguments for and against change and demonstrates independent reading and a well-justified conclusion; 2. Understand a variety of theories in law and emerging technologies and how to critique them analytically; 3. Engage in online self-assessment of legal solutions to specific problems created by the impact of science on society.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0500"},"AU5616":{"i":"AU5616","entryRequirements":"A Bachelor of Arts, or the equivalent and a minimum GPA  and a minimum level of competence in one of the languages offered for the degree. Non-native English speakers must meet minimum English language requirements.","strategicPurposeStatement":"PGCertTran graduates will gain a fundamental grasp of the principles, concepts and ideas that define translation and inform best practice. They will be competent practitioners equipped with a solid ethical understanding. They will be able to pursue personal professional goals with scope to consider a variety of career paths as well as further postgraduate study.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5616"},"VI0016":{"i":"VI0016","entryRequirements":"BSc(Hons) or BA(Hons) or Part 1 of the MSc, with passes in four level 8 psychology courses.","strategicPurposeStatement":"Graduates will be qualified for registration as clincial practitioners under the Psychologists Act (1981) and able to function as scientists in their practice as well as in a variety of other roles, eg. teaching.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI0016"},"LI6625":{"i":"LI6625","entryRequirements":"Entry is by completion of an undergraduate degree with a B average at 300 level.","strategicPurposeStatement":"Postgraduate Certificate in International Rural Development graduates will be able to contribute to knowledge, critically evaluate information and communicate effectively. They will be able to solve a range of both theoretical and practical problems and will have acquired the ability to work independently and with groups. Graduates will have an understanding of development processes, their application and their implications, particularly as they relate to areas of contextual focus (Agribusiness, Economics, Finance, Environmental Management, Tourism and Research Methods). Graduates will be equipped with the knowledge and skills required to address problems of poverty and sustainable development in rural communities through development policies, intervention strategies and institutional innovations.","developedBy":"Lincoln University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=LI6625"},"VI0032":{"i":"VI0032","entryRequirements":"A bachelor's honours degree with relevant prerequisites.","strategicPurposeStatement":"Graduates have an advanced body of knowledge and well-developed skills in intellectual analysis, criticism and problem-solving, which they apply to their chosen career. They will have mastered sophisticated subject matter through independent research, scholarship or creative activity conducted under supervision. Graduates may be able to continue to doctoral study.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI0032"},"OO0237":{"i":"OO0237","entryRequirements":"A Degree in Law or Medicine, or a Bachelor of Arts Degree with honours in Philosophy; or other acceptable qualification's and experience","strategicPurposeStatement":"This degree provides in-depth study, training and supervised research in areas of Bioethics and Health Law. It provides advanced knowledge in the field and the ability to study independently and carry out original research.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0237"},"WI0278":{"i":"WI0278","entryRequirements":"Normally concurrent enrolment in MSocSc, MPhil or DPhil","strategicPurposeStatement":"Graduates will have achieved a high level of competence and professionalism that will enable them to apply a broad range of psychological theories and concepts to both clinical practice and clinical research. They will have knowledge of a range of psychological models relevant to clinical psychology, and the clinical skills required to enable the use of psychological models across a range of problems and client groups.","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0278"},"MY3261":{"i":"MY3261","entryRequirements":"A Bachelor of Social Work or Bachelor of Social Work with Honours, or equivalent.","strategicPurposeStatement":"Graduates will be able to:  extend existing bodies of knowledge in an area specific to social work through intellectual independence, analytical rigour and critical evaluation.   ? master theoretical issues and research methods related to social work and critically analyse bodies of knowledge in social work and apply this knowledge to their own contexts.   ? critically read and appraise research in social work published in peer-reviewed social work and related journals.   ? apply knowledge of current theories of social service practice through the development of skills that allow the pursuit of scholarly interest in specific fields of social work practice.   ? apply knowledge of methodological and theoretical issues that relate to cultural competence as it relates to research and practice principles with Maori and diverse cultural groups.","graduateProfile":"A Bachelor of Social Work or Bachelor of Social Work with Honours, or equivalent.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY3261"},"WI0157":{"i":"WI0157","entryRequirements":"BA or BMPD degree or equivalent. Those students who have an honours degree or postgraduate diploma in a relevant field, may take 120 credits to complete the MMPD.","strategicPurposeStatement":"Graduates will have the ability to develop lines of argument and make sound judgements in accordance with basic theories and concepts in their subject(s), present, evaluate, and interpret qualitative and quantitative data and evaluate methodologies and develop critiques of them and, where appropriate, to propose new hypotheses. They will be able to contribute towards the enhancement of social, cultural, political, and economic development in New Zealand and overseas.","graduateProfile":"NA","educationPathway":"NA","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0157"},"VI0040":{"i":"VI0040","entryRequirements":"New Zealand Bachelors degree and two years relevant work experience or extensive practical, professional or scholarly experience.","strategicPurposeStatement":"Graduates will demonstrate problem-solving skills and techniques drawing on concepts and frameworks from economics, politics, philosophy and law, and how they can be applied to specialised areas including social policy, local government, health and education.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI0040"},"OO0028":{"i":"OO0028","entryRequirements":"Completion of 2 years of Bachelor of Laws degree to a high standard","strategicPurposeStatement":"This Honours degree programme provides a general and critical legal education. Graduates will be eligible for entry to the New Zealand legal profession and will have skills in legal research, including use of electronic databases and search tools, writing and advocacy.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0028"},"VI004Q":{"i":"VI004Q","entryRequirements":"Entry to the Master of Health Psychology requires a Bachelor of Health in Health Psychology, a Bachelor of Science in Psychology or Bachelor of Arts in Psychology or an equivalent qualification, with an average grade of at least B. Students who do not meet the minimum grade average may be permitted to enrol in the Postgraduate Diploma in Health Psychology and apply to progress to the Master of Health Psychology on the basis of their performance in the PGDipHlthPsyc.","strategicPurposeStatement":"Successful completion of the Master of Health Psychology followed by the Postgraduate Diploma in Health Psychology Practice will mean graduates are eligible to apply for registration as a psychologist. Employment options for graduates of the Master of Health who do not proceed to the PGDipHlthPsycPrac include health promotion, health policy, public health, and other mental health and wellbeing roles in both district health boards and non-governmental agencies. Other MHlthPsyc graduates may proceed to doctoral study and pursue academic and research careers.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI004Q"},"VI001J":{"i":"VI001J","entryRequirements":"An appropriate bachelors degree with at least a B- average and some background in economics, either professional or academic or both, as well as suitable quantitative skills.","strategicPurposeStatement":"Graduates will have an economic toolbox that they can apply to real-world problems. Graduates will be able to apply economic concepts and quantitative techniques using regional, national and global perspectives. They will be able to undertake applied economic research in a professional context and communicate this in ways appropriate for a range of stakeholders. They will be qualified to work at an advanced level in government departments and agencies, state-owned enterprises, banks and other private companies and consultancies in New Zealand, as well as internationally in organisations such as the Asian Development Bank, World Bank, IMF, the International Labour Organisation, and the United Nations Development Bank. Some graduates may be able to continue to the Master of Professional Economics (VI001G).","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI001J"},"AU0020":{"i":"AU0020","entryRequirements":"A New Zealand university entrance qualification or an approved alternative. Must meet entry requirements of each component degree. Selection criteria apply.","strategicPurposeStatement":"BA/LLB(Hons) graduates will demonstrate knowledge and understanding of the content and application of elements of both Arts and Law disciplines with additional enhanced research and writing skills within the law component.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU0020"},"VI001N":{"i":"VI001N","strategicPurposeStatement":"Graduates will have advanced knowledge of international relations, be able to conduct independent research and be capable of critical analysis of evidence and arguments. They will be qualified for careers in international affairs including governmental organisations, journalism, international institutions and civil-society organisations. Some graduates will be able to continue to the Master of International Relations (MIR, VI00A3) or a research-based masters degree. Alternatively, the postgraduate diploma may act as a step-off qualification from the MIR.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI001N"},"WI0814":{"i":"WI0814","entryRequirements":"A bachelors degree with at least second class honours (first division) or a masters degree awarded with distinction","strategicPurposeStatement":"Graduates will gain an in depth understanding of a specialist area of law, and be able to to produce research work of publishable quality that meets the highest international standards.","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0814"},"MY0625":{"i":"MY0625","entryRequirements":"Relevant Bachelor with Honours or Masters degree in Psychology with First Class or Second Class Division I Honours, or the equivalent; including specific papers and a project and sufficient personal qualities, ethical standards and professional experience","strategicPurposeStatement":"DClinPsy graduates will demonstrate advanced skills in the practice of Clinical Psychology according to the scientist-practitioner model in the areas of research, critical and analytic thinking, assessment and treatment. They will have the interpersonal and social skills to apply these skills in a manner that facilitates rapport with clients and other professionals and that is safe, ethical and culturally appropriate.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0625"},"OO0072":{"i":"OO0072","entryRequirements":"Bachelor of Theology degree or equivalent","strategicPurposeStatement":"This diploma provides advanced study plus an introduction to research in a chosen theological area. Recipients are capable of self-directed learning and intellectual independence, and can proceed to further postgraduate study.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0072"},"AK1333":{"i":"AK1333","entryRequirements":"A bachelor's degree or equivalent qualification.","strategicPurposeStatement":"PgDipSI graduates will have developed knowledge and understanding of how to identify and enable innovative responses to complex societal issues. Graduates will have skills in the critical, integrated, and effective use of a range of social innovation frameworks and tools including emerging technologies. They may be prepared for further postgraduate study in this field.","graduateProfile":"NA","educationPathway":"NA","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1333"},"AK3689":{"i":"AK3689","entryRequirements":"A relevant bachelor's degree completed to a merit standard.","strategicPurposeStatement":"MA graduates will be competent researchers with advanced analytical, planning and critical thinking skills. They will demonstrate a high level of professionalism, independence and leadership in their chosen field. They will have demonstrated the ability to engage in a sustained period of research, and may progress to further study at doctoral level.","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK3689"},"WI0829":{"i":"WI0829","entryRequirements":"A New Zealand University Entrance qualification or equivalent.","strategicPurposeStatement":"This conjoint degree gives students the opportunity to complete the requirements of two Bachelors degrees over a reduced period of time. Graduates will have knowledge and skills from both arts and management studies disciplines which gives them a good grounding for careers in many areas.","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0829"},"VI005M":{"i":"VI005M","entryRequirements":"Entry to the Postgraduate Diploma in Health Psychology Practice requires a Master of Health Psychology, including HPSY 503 Professional Practice and Skills in Psychological Practice, with an average grade of at least B+ and a selection interview to ensure students meet the requirements of the NZ Psychologists Board.","strategicPurposeStatement":"Successful completion of the Postgraduate Diploma in Health Psychology Practice, following the Master of Health Psychology, will mean graduates are eligible to apply for registration as a psychologist and to practice as psychologists competent in health psychology.","graduateProfile":"Assessment in the Postgraduate Diploma in Health Psychology Practice will be through a combination of individual and group assignments in reflective practice journals, case studies, written assignments, supervisors' placement evaluations, community presentations, tests and written and oral examinations.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI005M"},"VI001H":{"i":"VI001H","entryRequirements":"An appropriate bachelors degree with at least a B- average and some background in economics, either professional or academic or both, as well as suitable quantitative skills","strategicPurposeStatement":"Graduates will have an economic toolbox that they can apply to real-world problems. Graduates will be able to apply economic frameworks to business and policy-related issues. They will be able to undertake applied economic research in a professional context and communicate this in ways appropriate for a range of stakeholders. They will be qualified to work at a fairly advanced level in government departments and agencies, state owned enterprises, banks and other private companies and consultancies in New Zealand, as well as internationally. Some graduates may be able to continue to the Postgraduate Diploma in Professional Economics (VI001J) or the Master of Professional Economics (VI001G).","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI001H"},"LI7530":{"i":"LI7530","entryRequirements":"Entry is by completion of an undergraduate degree relevant to sport and recreation management with a B average at 300 level.","strategicPurposeStatement":"Graduates of this programme will have advanced understanding of the sport and recreation industry. Master of Sport and Recreation Management graduates will be able to create new knowledge, critically evaluate information and communicate effectively. They will have quantitative or qualitative analytic skills, or both, that will allow them to solve a range of both theoretical and practical problems. Graduates will also appreciate the benefit of committing to professional standards and be familiar with gender, ethnicity, equity and environmental issues.","developedBy":"Lincoln University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=LI7530"},"OO0074":{"i":"OO0074","entryRequirements":"Bachelor's or other degree requiring 4 years of study or equivalent","strategicPurposeStatement":"This degree involves supervised research in a chosen theological area. Graduates will have advanced knowledge in the field, and the ability to study independently, and to carry out original research to internationally recognised standards.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0074"},"AU5183":{"i":"AU5183","entryRequirements":"Admission is available to students selected on the basis of achievement in the first three years of the BSW.","strategicPurposeStatement":"BSW(Hons) graduates will demonstrate an advanced level of critical and analytical ability, and effective written and oral communication skills, that underpin sound social work practice and are commensurate with beginning professional practice. They will be critical, reflective practitioners able to pursue personal professional goals and further postgraduate study.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5183"},"MY1077":{"i":"MY1077","entryRequirements":"A relevant bachelors degree or scholarly work in conjunction with extensive professional experience and standing in leadership, managerial and planning positions in government or non-government security agencies.","strategicPurposeStatement":"Graduates will demonstrate knowledge of contemporary international security theory and practice; advanced analytical and planning skills; and competency to apply that knowledge in operations.","graduateProfile":"Not provided","educationPathway":"Not provided","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY1077"},"WI0138":{"i":"WI0138","entryRequirements":"A New Zealand university entrance qualification or equivalent.","strategicPurposeStatement":"This conjoint degree gives students the opportunity to complete the requirements of two Bachelors degrees over a reduced period of time. Graduates will have knowledge and skills from both law and social sciences disciplines which gives them a good grounding for careers in many areas. It is popular with students wishing to pursue careers in policy and research.","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0138"},"AU5752":{"i":"AU5752","entryRequirements":"Completed a Bachelors degree.","strategicPurposeStatement":"PGCertRegDev graduates will have specialised regional and iwi sector knowledge and will be equipped with the appropriate skills required to apply that knowledge in their chosen specialist field(s) of regional development policy or practice (e.g. environmental, social, educational).","graduateProfile":"Assessment methods include written assignments, individual and group projects, case analyses, and presentations","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5752"},"VI00V2":{"i":"VI00V2","entryRequirements":"A combination of essays and other written assignments.","strategicPurposeStatement":"Graduates will use their communication skills and knowledge of relevant principles and theories in entry-level information management roles. They may continue to the Postgraduate Diploma in Information Studies. The Certificate can be endorsed, if appropriate, in archives and records management or library science.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI00V2"},"AU5015":{"i":"AU5015","entryRequirements":"Masters degree in Health Psychology or equivalent","strategicPurposeStatement":"PGDipHealthPsych graduates will have developed the theoretical knowledge and practical skills required to enable them to apply for registration as a Registered Psychologist.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5015"},"OO0326":{"i":"OO0326","entryRequirements":"Professional social services qualification and 2 years relevant work experience","strategicPurposeStatement":"Recipients of this certificate are recognised by the social service industry as skilled in a chosen specialist area of the social service.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0326"},"VI001Z":{"i":"VI001Z","strategicPurposeStatement":"Graduates will have an in-depth knowledge of human migration, which they will use to analyse practical and theoretical problems and devise solutions. They will be able to evaluate and implement quantitative and qualitative methods used in migration research. They will interpret and reflect critically upon client needs and will communicate their ideas effectively in writing and orally. They will be qualified to work in public sector agencies, non-governmental bodies (both national and international), and research establishments that work on human migration. For some graduates, this qualification may lead to doctoral studies in geography.","graduateProfile":"Graduates will have an in-depth knowledge of human migration, which they will use to analyse practical and theoretical problems and devise solutions. They will be able to evaluate and implement quantitative and qualitative methods used in migration research. They will interpret and reflect critically upon client needs and will communicate their ideas effectively in writing and orally. They will be qualified to work in public sector agencies, non-governmental bodies (both national and international), and research establishments that work on human migration. For some graduates, this qualification may lead to doctoral studies in geography.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI001Z"},"VI0035":{"i":"VI0035","entryRequirements":"Bachelor of Laws with Honours or Bachelor of Laws with at least a 65% average.","strategicPurposeStatement":"Graduates of the LLM will have an advanced knowledge in a particular area of law. They will demonstrate expertise in legal research and writing and show ability in sustaining a legal argument.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI0035"},"AU5715":{"i":"AU5715","entryRequirements":"A Bachelor of Global Studies, or a Bachelor of Arts or Bachelor of Science in a relevant major, with a minimum GPA.","strategicPurposeStatement":"MGlobalSt graduates will be competent global citizens, able to combine analytical skills and related regional knowledge with research skills and practical knowledge to be well-prepared for leadership positions in a broad range of fields including international organisations in the public and private sectors, foreign affairs and diplomacy, NGOs, non-profit and human services, international media, think tanks and research institutes, teaching and tourism. Graduates may apply for a PhD in a relevant subject such as Geography, Politics and International Relations, or Public Policy.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5715"},"VI002T":{"i":"VI002T","strategicPurposeStatement":"Graduates will be able to critically analyse and engage in current museum and heritage practice in Aotearoa New Zealand. They will be equipped with the knowledge, skills and attributes to manage, interpret, display and care for cultural heritage objects, collections and buildings or sites in cultural heritage organisations. Graduates will be qualified to work in museums, galleries and heritage organisations in a range of roles, including management, policy, collections, exhibitions, public programmes and other areas of professional work. For most graduates this will be a professional degree leading to a career in the sector but some graduates may be able to continue to a master's degree by thesis or a PhD.","graduateProfile":"NA","educationPathway":"NA","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI002T"},"CN0135":{"i":"CN0135","entryRequirements":"An approved Bachelor's degree","strategicPurposeStatement":"Holders of this qualification will have a blend of traditional humanities-related skills and twenty first century applied ones. They will have an understanding of the moral and ethical issues surrounding technologies and the digital world, the ability to write clear, concise prose and an understanding of the technical constraints imposed by information systems. They will be comfortable using and critically assessing a range of technologies and the ability to apply those skills to new technologies as they encounter them. They will be suited to work in all new media and digital industries, but especially ones requiring a blend of analytical and technical skills. They would be suitable for work in research, relationship management, business analysis and project management in the cultural heritage sector, digital archiving and the creative sectors. They will be particularly suited to policy analysis position related to technology and culture and position that require communication across technical and non-technical teams. </Aim><Contents>One compulsory foundation in digital methods courses plus a further course to be chosen from a schedule, including the option of a digitally-oriented internship course.","graduateProfile":"Holders of this qualification will have a blend of traditional humanities-related skills and twenty first century applied ones. They will have an understanding of the moral and ethical issues surrounding technologies and the digital world, the ability to write clear, concise prose and an understanding of the technical constraints imposed by information systems. They will be comfortable using and critically assessing a range of technologies and the ability to apply those skills to new technologies as they encounter them. They will be suited to work in all new media and digital industries, but especially ones requiring a blend of analytical and technical skills. They would be suitable for work in research, relationship management, business analysis and project management in the cultural heritage sector, digital archiving and the creative sectors. They will be particularly suited to policy analysis position related to technology and culture and position that require communication across technical and non-technical teams. </Aim><Contents>One compulsory foundation in digital methods courses plus a further course to be chosen from a schedule, including the option of a digitally-oriented internship course.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0135"},"LI4568":{"i":"LI4568","entryRequirements":"Entry to the programme will normally require a B+ average in 300-level course in a prior undergraduate bachelors degree in a related area.","strategicPurposeStatement":"Graduates will have developed multi-disciplinary appreciation of the theory and methods for understanding the relationships between environment and society at an advanced level.","developedBy":"Lincoln University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=LI4568"},"OO0190":{"i":"OO0190","entryRequirements":"Acceptable performance in years 1 and 2 of the Bachelor of Physical Education degree programme.","strategicPurposeStatement":"Graduates of this degree programme will have in-depth knowledge and research experience in an area of physical education. Graduates are able to pursue personal professional goals and undertake further study at postgraduate level.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0190"},"OO0531":{"i":"OO0531","entryRequirements":"A bachelor's degree or equivalent.","strategicPurposeStatement":"The postgraduate diploma is for a range of professionals who are involved in leadership and management of faith-based organisations and who seek advanced professional education to enhance their work.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0531"},"VI004R":{"i":"VI004R","entryRequirements":"The Postgraduate Certificate in Health Psychology requires a Bachelor of Health in Health Psychology, a Bachelor of Science in Psychology, a Bachelor of Arts in Psychology, a Graduate Diploma in Health (Health Psychology specialisation), or a Graduate Diploma in Psychology.","strategicPurposeStatement":"Employment options for graduates of the Postgraduate Certificate in Health Psychology include health promotion, health policy, public health, and other mental health and wellbeing roles in both district health boards and non-governmental agencies.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI004R"},"MY0622":{"i":"MY0622","entryRequirements":"Candidates must be graduates of Massey University of at least 10 years standing.","strategicPurposeStatement":"Graduates will have made a significant contribution to knowledge in the fields of humanities or social sciences.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0622"},"OO0536":{"i":"OO0536","entryRequirements":"A bachelor's degree in Sport Development and Management, or equivalent.","strategicPurposeStatement":"Graduates will have a thorough understanding of sport, including its varied forms and cultures, its role, purpose and status in everyday life, and the way the sport sector is organised, administered and managed locally, nationally and globally.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0536"},"MY0152":{"i":"MY0152","entryRequirements":"A master's or doctor's degree in industrial/organisational psychology and employment which requires engagement with significant industrial/organisational issues.","strategicPurposeStatement":"Holders will be able to apply specialised psychological theory and research in motivation, social psychology, and human performance, to organisational settings.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0152"},"AK1048":{"i":"AK1048","entryRequirements":"A Bachelor of Arts degree or equivalent with a B grade average or higher in papers at level 7 or above.","strategicPurposeStatement":"MENMS graduates will have a critical understanding of new media practices in relation to a specified field of English Studies (applied linguistics, translation and interpreting, language teacher education and literacy). They will be capable of carrying out advanced research of a creative or empirical nature that examines the nexus between new media and the English language. They will be prepared for doctoral study.","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1048"},"AU5560":{"i":"AU5560","entryRequirements":"Admission to and successful completion of at least 30 points to the Master of Public Policy.  Further information is available from www.auckland.ac.nz","strategicPurposeStatement":"Graduates will know and understand the core principles, concepts and methods that define the field of public policy. They will be able to effectively scope and implement policy studies and critically assess policy studies produced by others.","graduateProfile":"NA","educationPathway":"NA","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5560"},"CN0165":{"i":"CN0165","entryRequirements":"An approved Bachelor's degree or equivalent.","strategicPurposeStatement":"Graduates will possess advanced knowledge of policy-making and governance in the unique contexts of Aotearoa New Zealand and Pacific states, with a strong foundation in cultural competency, critical thinking, and practical problem-solving. They will be equipped to contribute effectively to public, private, and community sector organisations, with particular sensitivity to the political, environmental, and developmental challenges facing Pacific communities.","graduateProfile":"A range of assessments will be used including coursework (e.g., essays, briefs, presentations, reflections) and a final examination.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0165"},"OO0530":{"i":"OO0530","entryRequirements":"A bachelor's degree or equivalent.","strategicPurposeStatement":"This master's degree programme is for a range of professionals who are involved in leadership and management of faith-based organisations and who seek advanced professional education to enhance their work.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0530"},"AU5168":{"i":"AU5168","entryRequirements":"Bachelor's degree with a major in a social science subject, or equivalent.","strategicPurposeStatement":"PGDipSocScResMeth graduates will be able to design and carry out social science research projects. They will understand and be able to apply a variety of research methods, and will be able to critically assess research exemplifying these methods.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5168"},"AU0037":{"i":"AU0037","entryRequirements":"A New Zealand university entrance qualification or an approved alternative. Must meet entry requirements of each component degree. Selection criteria apply.","strategicPurposeStatement":"BSc/LLB(Hons) graduates will demonstrate knowledge and understanding of the content and application of elements of both Science and Law disciplines with additional enhanced research and writing skills within the law component.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU0037"},"CN0145":{"i":"CN0145","entryRequirements":"An approved Bachelor's degree.","strategicPurposeStatement":"A graduate with a Postgraduate Certificate in Arts will have an advanced level of knowledge in their discipline or area of specialization, and have been introduced to theoretically sophisticated subject matter in their discipline or area of specialization.  They will have developed skills in the critical evaluation of academic literature in their discipline or area of specialization and have developed skills in the synthesis of information and the communication of their findings in both oral and written form.","graduateProfile":"Not applicable","educationPathway":"Not applicable","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0145"},"MY0216":{"i":"MY0216","entryRequirements":"A relevant bachelor's degree and professional experience.","strategicPurposeStatement":"Holders will have advanced knowledge and supervision skills in the social services field.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0216"},"OO0321":{"i":"OO0321","entryRequirements":"A bachelor's degree or appropriate professional qualification.","strategicPurposeStatement":"Holders of this certificate will be prepared for careers in leading, administering, and managing policy and practice relating to children's advocacy and well-being.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0321"},"OO0541":{"i":"OO0541","entryRequirements":"A bachelor's degree with an average grade of B+, or equivalent.","strategicPurposeStatement":"Graduates will have the capacity to assimilate information at depth in a field of study, and to impart to others a clear understanding of it.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0541"},"AU5509":{"i":"AU5509","entryRequirements":"A bachelor's degree in education, counselling, nursing, or social work and at least 3 years' practical experience in a relevant profession; an interview will be required.","strategicPurposeStatement":"Postgraduate Diploma in Counselling Theory graduates will know and understand the principles, concepts and ideas underpinning and informing counselling practices within a range of settings.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5509"},"MY0143":{"i":"MY0143","entryRequirements":"A Bachelor of Arts with a major in Development Studies, or equivalent; or a Bachelors degree and appropriate field or industry experience.","strategicPurposeStatement":"Graduates of the Postgraduate Certificate in International Development will be able to:  \n\r\n* Demonstrate knowledge and skills which can be applied in developing policy and strategies, and in managing and evaluating international development programmes.    \n\r\n* Critically and rigorously evaluate contemporary international development theories, policies and approaches.  \n\r\n*Interpret research findings and draw out relevant implications for development theory, policy and practice.  \n\r\nGraduates are particularly employable by a wide range of development agencies in the public, private and civil society sectors (including NGOs).","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0143"},"VI00Q4":{"i":"VI00Q4","entryRequirements":"A Bachelor's degree","strategicPurposeStatement":"Graduates will demonstrate knowledge of policy issues and resource management implications of development work at an advanced level.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI00Q4"},"AK1103":{"i":"AK1103","entryRequirements":"Bachelor's degree or equivalent.","strategicPurposeStatement":"PgCertAppPsych graduates will have foundational knowledge of key psychological theories and their application to real-world contexts. They will be able to identify behavioural influences and communicate psychological insights within professional settings. Graduates are prepared for further postgraduate study, including entry into the Postgraduate Diploma or Master of Applied Psychology. They will apply their understanding to enhance their effectiveness in current roles and contribute a psychological perspective to workplace and community settings.","graduateProfile":"Courses employ a diverse range of assessments, including case analyses, simulation-based interventions, reflective practice portfolios, collaborative presentations.","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1103"},"VI003E":{"i":"VI003E","entryRequirements":"A bachelor's degree in a relevant subject, with an average grade of B or better.","strategicPurposeStatement":"Graduates will be able to apply their multidisciplinary practical and theoretical skills to politics, government and related fields.  They will be able to think across boundaries and engage critically with a range of different material.  They will be skilled oral and written communicators who apply critical and reflective thinking, logic and persuasion to their work.  Graduates will be able to work in politics, the government sector and NGOs.  The MPPE is strongly focused on employability but graduates may be able to continue to doctoral study, depending on their research background.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI003E"},"OO0333":{"i":"OO0333","entryRequirements":"A degree or appropriate professional qualification requiring at least three years of full-time study, or equivalent.","strategicPurposeStatement":"This diploma programme provides a qualification for professionals who work with children in such fields as education, law, health, social work and psychology.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0333"},"OO0512":{"i":"OO0512","entryRequirements":"A bachelor's degree or equivalent.","strategicPurposeStatement":"Graduates of this degree programme will have an in-depth knowledge of economic theory and practice, and will have demonstrated evidence of independent critical thought and judgement and the ability to solve complex unstructured and structured problems. They will have the ability to think logically, analytically and critically with respect to the theory and practice of Economics.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0512"},"WI0891":{"i":"WI0891","strategicPurposeStatement":"This conjoint degree gives students the opportunity to complete the requirements of two Bachelors degrees over a reduced period of time. Graduates will have knowledge and skills from both law and communication studies disciplines which gives them a good grounding for careers in many areas.","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0891"},"CN0334":{"i":"CN0334","entryRequirements":"An approved Bachelor's degree or equivalent.","strategicPurposeStatement":"Graduates will have advanced knowledge and skills in criminal justice plus enhanced employment options. They will have gained advanced skills in locating, evaluating, and synthesising information from a range of primary and secondary sources relevant to a research topic. the ability to analyse critically key issues of principle and policy in relation to criminal justice systems and their operation in practice, knowledge of tikanga and Te Ao Maori as they relate to criminal justice practice and research. The award will allow an upgrade pathway for admission to the Master of Criminal Justice","graduateProfile":"A range of assessments will be used including coursework, tests and formal examinations.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0334"},"WI0153":{"i":"WI0153","entryRequirements":"Bachelors degree or equivalent and evidence of at least two years' prior experience and/or professional preparation in counselling, and selection as a suitable person for the Counselling programme.","strategicPurposeStatement":"Graduates will have a knowledge and understanding of the diverse range of mainstream counselling approaches with an emphasis on a specific body of ideas, skills and approaches that draw upon constructionist and postmodern theories and practices, that are often called \"narrative\" approaches. They will have the skills enabling them to develop professional attitudes, knowledge and competencies in the areas of counselling, group leadership, mediation and family therapy, and will have the ability to strengthen people's talents and abilities and their own knowledge about how to combat oppressive circumstances in their lives.","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0153"},"WI0912":{"i":"WI0912","entryRequirements":"Entry by invitation based on results of first three years of BSW","strategicPurposeStatement":"Graduates will have knowledge and skills in the theory and practice of Social Work such that they are able to enter the social work profession as beginning social workers. Graduates will have knowledge of research methods in social work and be able to apply these in supervised research and will be equipped to proceed to advanced study in the subject.","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0912"},"MY1096":{"i":"MY1096","entryRequirements":"University admission requirements, and a relevant Bachelors degree or be able to demonstrate scholarly work in conjunction with extensive relevant professional experience appropriate for Admission with Equivalent Status.","strategicPurposeStatement":"Graduates will have advanced knowledge of contemporary international security theory and practice, an ability to evaluate critically the findings and discussions in international security literature, use of evidence to research, analyse and argue critically in relation to international security issues. An ability to apply their knowledge to new situations in the international security environment. An ability to assess an international security situation and propose a solution, effective communication skills in the security context.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY1096"},"WI0254":{"i":"WI0254","entryRequirements":"Bachelor of Social Sciences with a major in Psychology.","strategicPurposeStatement":"Graduates have advanced knowledge of the underlying concepts and principles associated with the area(s) of study, that is, psychological theory and research, particularly in relation to the psychology of work-related attitudes and behaviours and the functioning of organisations.","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0254"},"CN0306":{"i":"CN0306","entryRequirements":"Bachelor of Laws","strategicPurposeStatement":"This degree provides opportunities for graduate law students to undertake advanced coursework and research under close supervision of faculty in chosen areas of the law. The LLM programme aims to encourage analytical and critical skills at an advanced level in an appropriate legal framework and to engage in creative research in areas relating to the nature, content and direction of the law.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0306"},"OO0325":{"i":"OO0325","entryRequirements":"Professional social services qualification and 2 years relevant work experience","strategicPurposeStatement":"Recipients of this diploma are recognised by the social service industry as skilled in a chosen specialist area of the social service.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0325"},"AU5716":{"i":"AU5716","entryRequirements":"A Bachelors degree in a relevant major with a minimum GPA.","strategicPurposeStatement":"PGDipGlobalSt graduates will acquire skills as global citizens who combine analytical skills and related regional knowledge with research skills and practical knowledge to be well prepared for jobs in a broad range of fields including international organisations in the public and private sectors, foreign affairs and diplomacy, NGOs, non-profit and human services, international media, think tanks and research institutes, teaching and tourism.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5716"},"MY0229":{"i":"MY0229","entryRequirements":"Appropriate degree or equivalent. Relevant work in a related area to whanau development within three years of application for admission.","strategicPurposeStatement":"Graduates will demonstrate confidence in interacting with whanau and Maori communities, and knowledge in relation to whanau endeavours. Graduates will have an understanding of whanau dynamics and whanau in society. They will be able to discuss barriers and opportunities, will have an understanding of whanau structures, functional capacities and indicators of whanau wellbeing, and will be able to utilise research to inform whanau development. They will have an advanced understanding of whanau dynamics and the impact of policies, be able to plan and implement interventions in a particular area of whanau development and undertake research.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0229"},"VI001Q":{"i":"VI001Q","entryRequirements":"A bachelor's degree or equivalent.","strategicPurposeStatement":"Graduates will have theoretical and applied knowledge of museum and heritage studies.  Some graduates may be able to continue to the Postgraduate Diploma in Museum and Heritage Studies (VI001R).","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI001Q"},"CN0785":{"i":"CN0785","entryRequirements":"An approved Bachelor's degree or recognised equivalent.","strategicPurposeStatement":"Graduates will gain knowledge of theoretical approaches to translation and interpreting and will develop general skills of translating and/or interpreting from and into their second language. Graduates choosing to specialise in computer-assisted translation will have developed critical thinking for the use of computer-assisted translation tools, including captioning and translation memory. Graduates specialising in community translation will have acquired knowledge and skills necessary to translate and interpret for the culturally and ethnically diverse communities of Aotearoa New Zealand as well as the ability to make informed ethical decisions in their professional practice, including in crisis scenarios. Upon completing these degrees, students will have the level equivalent to provisional interpreter or certified translator, according to the NAATI framework.","graduateProfile":"A range of assessments will be used including coursework and examination.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0785"},"AU5500":{"i":"AU5500","entryRequirements":"Degree of Bachelor of Laws or the Degree of Bachelor of Laws (Honours).","strategicPurposeStatement":"Graduates of the Postgraduate Certificate in Law will have a specialised knowledge and understanding demanded by the legal profession and community, in the subjects they have chosen. This knowledge and understanding will enable them to be competent and reflective practitioners able to better serve their clients and society.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5500"},"AK1063":{"i":"AK1063","entryRequirements":"A relevant bachelor's degree with a B grade average or higher in papers at level 7 or equivalent.","strategicPurposeStatement":"PgDipLC graduates will have advanced critical knowledge and understanding in their chosen areas of focus in Applied Linguistics, which may include the proficiency, linguistic and/or cultural knowledge of an Asia-Pacific language (or their own language/s), language analysis, language and literacy education, multilingualism and culture, and translation and interpreting. Graduates will also have advanced critical knowledge about the relationship between language and culture. They will be critical and reflective.","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1063"},"OO0524":{"i":"OO0524","entryRequirements":"An appropriate bachelor's degree with an average grade of at least B in the final year of study, or equivalent.","strategicPurposeStatement":"Graduates of this degree programme will have advanced academic skills and research abilities within the discipline of Social and Community Work","graduateProfile":"NA","educationPathway":"NA","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0524"},"MY0263":{"i":"MY0263","entryRequirements":"a) meet the University admission requirements as specified and:  b) shall have been awarded or qualified for a relevant Bachelor's degree having achieved a grade average of at least a B-, or equivalent","strategicPurposeStatement":"Holders will have developed advanced knowledge and skills appropriate for work in general museums, art museums and heritage agencies.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0263"},"WI0815":{"i":"WI0815","entryRequirements":"A graduate of a New Zealand university. Candidates may not present themselves for the degree until at least ten years after graduation to their first degree.","strategicPurposeStatement":"LLD graduates have knowledge and skills in law that is superior in both knowledge and application to that of their undergraduate and post-graduate contemporaries. They are undisputed national and/or international experts and leaders in specialist areas of law.","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0815"},"VI005H":{"i":"VI005H","entryRequirements":"A Bachelor's degree in Linguistics or a related subject with an average grade of B or better.","strategicPurposeStatement":"Students in the Postgraduate Diploma of Linguistics will be part of the research culture of the Linguistics programme within the School of Linguistics and Applied Language Studies. The PGDipLing degree will prepare graduates who:   *       have specialised knowledge of some current areas of linguistic research, including those of an interdisciplinary nature   *       have a grounding in the use of quantitative and qualitative methods for collecting and analysing linguistic data   *       are able to make critically informed decisions about the methods appropriate for investigating different research questions   *       are able to develop their own complex ideas related to linguistic structure and language use based on a sound understanding of relevant research   *       communicate effectively and accurately about linguistic research in different contexts and through different media   *       demonstrate intellectual integrity and a thorough understanding of the ethics of scholarship.      With these attributes, developed in the formal curriculum and tested through academic assessment, graduates will have the knowledge, skills and experience to undertake semi-independent advanced research in linguistics, including interdisciplinary perspectives.   The programme develops in students high-level transferable skills for language-related fields, including language and social policy, marketing, and speech technology.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI005H"},"VI001R":{"i":"VI001R","entryRequirements":"A bachelor's degree or equivalent.","strategicPurposeStatement":"Graduates will demonstrate advanced knowledge of museum and heritage studies and will be able to conduct independent research, undertake advanced evaluation and apply practical skills appropriate to the cultural sector.   Some graduates may be able to continue to the Master of Museum and Heritage Studies (MMHS, VI00F2). Alternatively, the postgraduate diploma may act as a step-off qualification from the MMHS.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI001R"},"AU0333":{"i":"AU0333","entryRequirements":"Honours or Masters degree in Psychology including specific \"papers\" (courses) and a dissertation","strategicPurposeStatement":"DClinPsy graduates will: demonstrate advanced skills in research in Clinical Psychology; have advanced knowledge of methods of practice in Clinical Psychology; provide safe and ethical psychological services in mental health and other agencies","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU0333"},"AK3912":{"i":"AK3912","entryRequirements":"Bachelor Degree","strategicPurposeStatement":"Postgraduate Certificate in Sport and Exercise graduates will have advanced knowledge within a specialist field of sport and exercise. They will have developed skills in critical thinking, problem solving, and communication and be prepared for further postgraduate study.","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK3912"},"MY0173":{"i":"MY0173","entryRequirements":"A Bachelor degree and at least one full-time year of relevant teaching experience, or equivalent","strategicPurposeStatement":"Graduates of the Massey University Postgraduate Certificate in Applied Linguistics will have an understanding of issues relating to the teaching, learning and use of languages in a range of contexts.  Graduates will possess the necessary foundations to pursue further postgraduate study in Applied Linguistics or Second Language Teaching , subject to appropriate academic standing.","graduateProfile":"Graduates of the Massey University Postgraduate Certificate in Applied Linguistics will have an understanding of issues relating to the teaching, learning and use of languages in a range of contexts.  Graduates will possess the necessary foundations to pursue further postgraduate study in Applied Linguistics or Second Language Teaching , subject to appropriate academic standing.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0173"},"VI00A3":{"i":"VI00A3","entryRequirements":"Bachelor's degree with First or Second Class Honours or extensive experience.","strategicPurposeStatement":"Graduates will have gained an overview of world politics and advanced their research skills with intensive study in some area of international relations.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI00A3"},"AU5758":{"i":"AU5758","entryRequirements":"Completed a Bachelors degree, Bachelors Honours degree or Postgraduate Diploma with a minimum GPA and relevant professional experience, or a Bachelors degree and passed 60 points towards a Postgraduate Certificate in Regional Development.","strategicPurposeStatement":"MRegDev graduates will have specialised regional and iwi sector knowledge and will be equipped with the appropriate skills required to apply that knowledge in their chosen specialist field(s) of regional development policy or practice (e.g. environmental, social, educational). MRegDev graduates will also be able to initiate, design, conduct and report on an independent development research project and a substantive research-based evaluation project related to their specialist fields of regional development policy or practice.","graduateProfile":"Assessment methods include written assignments, individual and group projects, case analyses, and presentations","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5758"},"AU5175":{"i":"AU5175","entryRequirements":"A bachelors degree, current employment in a health counselling, social or human services or other appropriate professional context and at least two years relevant professional experience.","strategicPurposeStatement":"PGDipProfSup graduates will know and understand the principles, concepts and ideas that define professional supervision and inform supervision practice, including supervision in specific contexts. They will be critical, reflective practitioners able to pursue personal professional goals and pursue further postgraduate study.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5175"},"WI1011":{"i":"WI1011","strategicPurposeStatement":"This qualification aims to prepare students for a professional career as behaviour analysts. The programme provides students with a sound foundation of behaviour analytic concepts and principles, and the fundamentals of professional and ethical practice in applied behaviour analysis (ABA). Students will learn many practical skills, including how to define and measure behaviour, create and evaluate behaviour change programmes, and conduct functional analyses, in order to improve socially significant behaviours.","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI1011"},"AU5561":{"i":"AU5561","entryRequirements":"A Bachelor of Arts (Honours) in a relevant subject, or a Bachelors degree in a relevant subject, or an equivalent qualification, and a minimum Grade Point Average (GPA).","strategicPurposeStatement":"Graduates will have advanced knowledge and skills in the study of conflict and terrorism at both the inter- and intra-state level, and will be practised in engaging in high-level analysis and critique of these. They will have access to a range of career opportunities capable of policy-relevant engagement in public and private sector employment and/or further scholarship.","graduateProfile":"NA","educationPathway":"NA","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5561"},"MY0412":{"i":"MY0412","entryRequirements":"A relevant bachelor's degree in social work with grades which meet College and University requirements for admission to advanced degrees.","strategicPurposeStatement":"Graduates will demonstrate (1) advanced knowledge in social work theory and practice; (2) advanced analytical and communication skills, (3) ability to work independently, and (3) ability to complete a piece of supervised research to an internationally acceptable level.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0412"},"WI0870":{"i":"WI0870","entryRequirements":"A New Zealand university entrance qualification or equivalent","strategicPurposeStatement":"This conjoint degree gives students the opportunity to complete the requirements of two Bachelors degrees over a reduced period of time. Graduates will have knowledge and skills from both law and business analysis disciplines which gives them a good grounding for careers in many areas. The LLB will be awarded with honours only where the students grades in the final year justify the award.","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0870"},"AU5512":{"i":"AU5512","entryRequirements":"A Bachelor of Social Work or a Bachelor of Social Work (Hons) or a Postgraduate Diploma in Professional Supervision or a Postgraduate Diploma in Health Sciences (Social Work) or a Postgraduate Diploma in Social Work.","strategicPurposeStatement":"MSW graduates will be able to initiate, design, conduct and report independent and original research from a defined project.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5512"},"LI6590":{"i":"LI6590","entryRequirements":"Entry is by completion of an undergraduate degree in a related area of study with a B average at 300 level. If students perform well in the Postgraduate Diploma in Land and Society, then they will be equipped to continue to study at the Masters or even PhD level.","strategicPurposeStatement":"Graduates of this programme will have developed an advanced, multi-disciplinary appreciation of the theory and methods for understanding the interaction of people, societies and their physical and natural environments. They will also have gained comprehensive skills in applying that theory to significant 'real world' problems. Graduates of the Postgraduate Diploma in Land and Society will be able to contribute to knowledge regarding socio-physical phenomena, critically evaluate information, and communicate this knowledge effectively. They will have quantitative or qualitative analytic skills, or both, that will allow them to solve a range of both theoretical and practical problems. Graduates will be equipped with advanced research skills and capable of high-level research.","developedBy":"Lincoln University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=LI6590"},"AK2017":{"i":"AK2017","entryRequirements":"A bachelor's degree, or a relevant professional qualification or experience approved by the dean (or representative) to be equivalent to a bachelor's degree.","strategicPurposeStatement":"PgDipGast graduates will have advanced knowledge and understanding of gastronomy. They will be able to engage in research in the area, taking an analytical, critical and reflective approach and be prepared for further postgraduate study.","graduateProfile":"NA","educationPathway":"NA","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK2017"},"OO0004":{"i":"OO0004","entryRequirements":"A bachelor's degree or equivalent.","strategicPurposeStatement":"This degree programme involves supervised research in a chosen arts or social science subject. Graduates will have advanced knowledge in the field, and the ability to study independently and carry out original research to internationally recognised standards.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0004"},"WI0145":{"i":"WI0145","strategicPurposeStatement":"Graduates will able to provide a systematic and coherent account of the knowledge, ideas, principles, concepts, research methods, and problem-solving techniques in the field of sport and leisure studies.","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0145"},"AU5182":{"i":"AU5182","entryRequirements":"Completed the requirements for an approved Bachelors Degree with a minimum Grade Point Average (GPA) and  passed any specified prerequisite courses.","strategicPurposeStatement":"MPP graduates will know and understand the core principles, concepts and methods that define the field of public policy. They will be able to effectively scope and implement policy studies and critically assess policy studies produced by others.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5182"},"WI0939":{"i":"WI0939","entryRequirements":"Bachelors degree in Social Work or equivalent and must be eligible for registration.","strategicPurposeStatement":"The Master of Social Work degree provides graduates with a combination of practical research skills and advanced theoretical knowledge and an understanding of specific fields of social work practice and decision-making, enhanced by inter-disciplinary papers from related subjects.","graduateProfile":"NA","educationPathway":"NA","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0939"},"VI00O2":{"i":"VI00O2","entryRequirements":"Bachelor's degree","strategicPurposeStatement":"Holders of the certificate will have gained an improved understanding of strategic and security issues.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI00O2"},"AU5659":{"i":"AU5659","entryRequirements":"Completed the requirements for a Bachelors degree and  passed the specified prerequisite courses in the selected subject for the Master of Arts, or the Master of Public Policy, with a minimum Grade Point Average (GPA)","strategicPurposeStatement":"PGCertArts graduates will know and understand the principles, concepts and ideas relevant to a subject in Arts. They will be critical, reflective, adept at problem-solving, and prepared for postgraduate study.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5659"},"CN0787":{"i":"CN0787","entryRequirements":"An approved Bachelor's degree.","strategicPurposeStatement":"Graduates will have an advanced knowledge of theoretical approaches to translation and interpreting and will develop specialised advanced skills of translating and/or interpreting from and into their second language. Graduates choosing to specialise in computer-assisted translation will have developed critical thinking for the use of computer-assisted translation tools, including captioning and translation memory. Graduates specialising in community translation will have acquired advanced knowledge and skills necessary to translate and interpret for the culturally and ethnically diverse communities of Aotearoa New Zealand as well as the ability to make informed ethical decisions in their professional practice, especially in crisis scenarios.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0787"},"WI0808":{"i":"WI0808","entryRequirements":"BSpLS degree or equivalent. Those students who have an honours degree in a relevant field, may take 120 credits to complete the MSpLS.","strategicPurposeStatement":"Graduates will have advanced understanding and knowledge about the specialist body of theoretical and applied topics relevant to sport and leisure studies. They will understand the underlying concepts and principles associated with sport and leisure studies, different approaches to solving problems in sport and leisure studies and particular social, political and cultural issues within New Zealand relevant to their specific interest with sport and leisure.","graduateProfile":"NA","educationPathway":"NA","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0808"},"AU5141":{"i":"AU5141","entryRequirements":"A New Zealand university entrance qualification or an approved alternative. Must meet entry requirements of each component degree. Selection criteria apply.","strategicPurposeStatement":"BE(Hons)/LLB(Hons) graduates will demonstrate knowledge and understanding of the content and application of elements of both Engineering and Law disciplines with additional enhanced research and writing skills within the law component","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5141"},"CN0788":{"i":"CN0788","strategicPurposeStatement":"Translation and Interpreting","graduateProfile":"Graduates will gain knowledge of theoretical approaches to translation and interpreting and will develop specific skills of translating and/or interpreting from and into their second language. Graduates choosing to specialise in computer-assisted translation will have developed critical thinking for the use of computer-assisted translation tools, including captioning and translation memory. Graduates specialising in community translation will have acquired knowledge and skills necessary to translate and interpret for the culturally and ethnically diverse communities of Aotearoa New Zealand as well as the ability to make informed ethical decisions in their professional practice, including in crisis scenarios. Graduates will supplement their theoretical knowledge of the discipline(s) with practical experience in translation and interpreting in language-specific scenarios, including advanced language proficiency classes, internship opportunities, a portfolio, as well as more advanced and individual research.  Upon completing these degrees, students will have the level equivalent to provisional interpreter or certified translator, according to the NAATI framework.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0788"},"WI0034":{"i":"WI0034","entryRequirements":"BSocSc degree or equivalent.","strategicPurposeStatement":"Graduates will have detailed and advanced knowledge in at least one Social Science subject, as well as skills in their subject of choice. They will have the opportunity to gain critical thinking, oral and communication skills.","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0034"},"WI0031":{"i":"WI0031","entryRequirements":"BA degree or equivalent","strategicPurposeStatement":"Graduates will have detailed and advanced knowledge and skills in at least one Humanities subject. They will have also had the opportunity to gain critical thinking, oral and communication skills.","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0031"},"VI002G":{"i":"VI002G","strategicPurposeStatement":"Graduates will have knowledge of the interdisciplinary theoretical and comparative literature on human migration and of relevant research methodologies, which they will use to develop an original research proposal. They will communicate their ideas effectively in writing and orally. They will enhance their existing career prospects in public sector agencies and non-governmental bodies that work on human migration. Some graduates will be able to continue to the Master of Migration Studies (VI001Z). The PGDipMigS also acts as an exit qualification for the MMigS.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI002G"},"OO0030":{"i":"OO0030","entryRequirements":"Bachelor of Laws degree or Bachelor of Laws degree with honours or equivalent","strategicPurposeStatement":"This degree involves supervised research in a chosen topic in Law. Graduates will have advanced knowledge in the field, and the ability to study independently, and to carry out original research to internationally recognised standards.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0030"},"AU5712":{"i":"AU5712","entryRequirements":"A New Zealand university entrance qualification or an approved alternative. Must meet entry requirements of each component degree. Selection criteria apply.","strategicPurposeStatement":"BC/LLB(Hons) graduates will demonstrate knowledge and understanding of the content and application of elements of both Communication and Law disciplines.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5712"},"AK1334":{"i":"AK1334","entryRequirements":"In order to be admitted to the Postgraduate Certificate in Social Innovation an applicant must have completed a bachelor's degree or equivalent qualification.","strategicPurposeStatement":"PgCertSI graduates will have developed knowledge and understanding of how to identify innovative responses to complex social issues. Graduates will begin to build their skills in the use of a range of social innovation frameworks and tools including emerging technologies. They may be prepared for further postgraduate study in this field.","graduateProfile":"NA","educationPathway":"NA","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1334"},"AU5566":{"i":"AU5566","entryRequirements":"A Bachelors degree with at least 60 points in social science subjects, or a Bachelors degree and an un-awarded Postgraduate Certificate in Social and Community Leadership, or equivalent qualifications, and a minimum Grade Point Average (GPA).","strategicPurposeStatement":"Graduates of the MSCL will have specialised sector leadership knowledge and will be equipped with the appropriate skills required to apply that knowledge in their chosen specialist field of practice. These graduates will fill a demand for these knowledge, skills, and dispositions as identified by the community and social service, not-for-profit and social enterprise sectors in Aotearoa New Zealand and overseas. They will be critical, reflective leaders able to pursue both personal professional goals and further postgraduate study. In addition, graduates of the MSCL will be able to initiate, design, conduct and report independent and original research and/or programme evaluations for a defined project.","graduateProfile":"NA","educationPathway":"NA","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5566"},"VI00O1":{"i":"VI00O1","strategicPurposeStatement":"Holders of the diploma will have gained an advanced understanding of strategic analysis, security and related areas.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI00O1"},"AU5546":{"i":"AU5546","entryRequirements":"Bachelors degree, Bachelors Honours degree or Postgraduate Diploma, or an equivalent qualification, in a relevant subject","strategicPurposeStatement":"Graduates will have advanced knowledge and skills in indigenous development and research methodologies.","graduateProfile":"Not applicable","educationPathway":"Not applicable","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5546"},"AU0358":{"i":"AU0358","entryRequirements":"Bachelor of Laws.","strategicPurposeStatement":"LLM graduates will have undertaken advanced legal study and research in an area of specialization or across a broad range of legal subjects and will have enhanced professional and legal knowledge and skills.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU0358"},"VI005E":{"i":"VI005E","entryRequirements":"The entry requirements for the PGDipAppLing are a Bachelor's degree (or equivalent qualification) with a grade average of B or better in Linguistics, English Language, Education or a language other than English (or another relevant degree), and at least two years of professional experience in language education or another area of applied linguistics or a related field. Applicants without relevant experience will be considered on a case-by-case basis and may be expected to complete bridging courses depending on the nature and extent of their previous experience and qualifications.","strategicPurposeStatement":"Graduates from the PG DipAppLing will demonstrate advanced knowledge of selected topics in applied linguistics. They will be able to engage critically and creatively with applied linguistics research on these topics and apply this knowledge to understanding language-related real-life problems. The programme develops in students high-level transferable skills for language-related fields, including language education planning.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI005E"},"WI0130":{"i":"WI0130","entryRequirements":"Students who have passed Law 1 and Law 2 for the LLB are eligible for consideration.","strategicPurposeStatement":"Graduates have a comprehensive knowledge of a substantial range of concepts, principles and rules of law in the New Zealand legal system, and of its major institutions and procedures. They will also have obtained high levels of mastery of content and understanding of law, and through their own research have obtained detailed additional levels of understanding of particular issues.","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0130"},"AK3911":{"i":"AK3911","entryRequirements":"Bachelor of Sport and Recreation or Graduate Diploma in Sport and Exercise or approved relevant experience.","strategicPurposeStatement":"Postgraduate Diploma in Sport and Exercise graduates will have specialist skills in a chosen field of sport and exercise essential to perform at a high professional level. They will be able to apply contemporary theory to current practice and have demonstrated analytical and problem solving skills and be prepared for further postgraduate study.","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK3911"},"CN0975":{"i":"CN0975","entryRequirements":"A Bachelor's degree or equivalent or relevant skills and knowledge acquired through appropriate work or professional experience.","strategicPurposeStatement":"Graduates of the PGCertCBT will be able to:  (a) Demonstrate an appreciation of how colonisation and racism has contributed to poorer (mental) health outcomes in Maori.  (b) Demonstrate an appreciation of how Maori models of wellbeing overlap and differ from western models of health  (c) Be aware of how to ethically set up a treatment frame to work with clients with mental health difficulties and how to adapt this for Maori in respect of contact and interviewing  (d) Demonstrate fundamental knowledge of how CBT theory accounts for the development and maintenance of common mild to moderate mental health presentations and substance misuse issues.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0975"},"OO0513":{"i":"OO0513","entryRequirements":"A bachelor's degree or equivalent.","strategicPurposeStatement":"Graduates of this diploma programme will possess a deep, coherent and extensive knowledge of ethical and legal issues arising in health care, including theories relating to law and ethics, coupled with knowledge of the fundamental contribution of research to this area of study.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0513"},"OO0507":{"i":"OO0507","entryRequirements":"A bachelor's degree with an average grade of B+ in the final year of study, or equivalent.","strategicPurposeStatement":"This programme provides chaplains with specialised training. Graduates will be able to demonstrate a highly developed ability to integrate thought and action at an advanced level, integrate professional and intellectual ability, exercise independent judgement, undertake analysis, research a topic, and reflect professionally upon one's own and others' actions.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0507"},"WI0865":{"i":"WI0865","entryRequirements":"A New Zealand university entrance qualification or equivalent.","strategicPurposeStatement":"This conjoint degree gives students the opportunity to complete the requirements of two Bachelors degrees over a reduced period of time. Graduates will have knowledge and skills from both law and sport and leisure studies disciplines which gives them a good grounding for careers in many areas.   The LLB will be awarded with honours only where the student's grades in the final year justify the award.","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0865"},"AK3914":{"i":"AK3914","entryRequirements":"A relevant Bachelor's Degree or equivalent completed to a Merit standard.","strategicPurposeStatement":"Graduates will have advanced knowledge and understanding in their chosen academic field. They will be critical and reflective, with applied research capability. They will have demonstrated the ability to engage in a period of research and may progress to further study at doctoral level.","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK3914"},"WI1030":{"i":"WI1030","entryRequirements":"Candidates for the Postgraduate Certificate would normally have qualified for the award of a Bachelors Degree or equivalent.","strategicPurposeStatement":"Graduates of the Postgraduate Certificate of Professional Practice in Social and Community Services will be well prepared for further postgraduate studies in social work, health and other related areas or be well placed to respond to the needs of the community.","graduateProfile":"Examination or internal assessment.","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI1030"},"CN0195":{"i":"CN0195","entryRequirements":"A Bachelor's degree with a major or equivalent in Te Reo Maori.","strategicPurposeStatement":"Graduates are fluent speakers and have an advanced knowledge of Te Reo Maori, with introductory research-based knowledge of the language. They will have achieved linguistic competence and critical thinking about a number of contemporary and historical aspects of the language.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0195"},"AK1067":{"i":"AK1067","entryRequirements":"A Bachelor of Arts in Criminology and Criminal Justice or an equivalent qualification with a B grade average or higher in the papers at level 7.","strategicPurposeStatement":"MCrimCJ graduates will have advanced knowledge and understanding of Criminology and Criminal Justice. They will be critical and reflective, with applied research capability. They will have demonstrated the ability to engage in a limited period of research. Some may progress to further study at doctoral level.","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1067"},"AU5771":{"i":"AU5771","entryRequirements":"Completed a Bachelors degree with a minimum GPA.","strategicPurposeStatement":"Postgraduate Certificate in Intellectual Property graduates will have gained an in-depth understanding of intellectual property law, and in particular, the law regarding to trade marks and will have also obtained the knowledge and skills necessary for professional practice.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5771"},"MY0440":{"i":"MY0440","entryRequirements":"Admission to the 240 credits programme is open to students who have completed a Bachelor of Sport and Exercise or equivalent sport-related degree with at least an overall B grade average. Admission to the 120 credits programme by thesis is open to students who have completed a Bachelor of Sport and Exercise degree with Honours or an equivalent sport-related degree, or who have completed the Postgraduate Diploma in Sport and Exercise; with at least an overall B grade average.","strategicPurposeStatement":"Graduates will build on the interdisciplinary approach to the study of sport and exercise to an advanced level. They will have advanced knowledge consequent to their major area of bachelors level study. They will show in-depth knowledge of varying points of view and research traditions in the field and can capably interrogate existing assumptions and practices from more than one academic standpoint. They will have a sophisticated grasp of the key underlying principles of the facets of sport and exercise and be able to implement and adapt these principles within a complex and rapidly-changing professional environment. They will be competent independent researchers who have demonstrated the ability to critically evaluate and employ research methodologies to an internationally recognised level. They will be creative in their approach to research design, discovery and problem-solving, with a developed ethos of cross-disciplinary and inter-sectoral collaboration as it applies within the sport and exercise field.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0440"},"VI005F":{"i":"VI005F","entryRequirements":"A Bachelor's degree in Linguistics or a related subject with an average grade of B or better.","strategicPurposeStatement":"Students in the Postgraduate Certificate of Linguistics will be part of the research culture of the Linguistics programme within the School of Linguistics and Applied Language Studies. The PGCertLing degree will prepare graduates who:  *       have specialised knowledge of at least one current area of linguistic research  *       have a grounding in the use of quantitative and qualitative methods for collecting and analysing linguistic data  *       are able to make critically informed decisions about the methods appropriate for investigating different research questions  *       are progessing towards being able to develop their own complex ideas related to linguistic structure and language use based on a sound understanding of relevant research  *       communicate effectively and accurately about linguistic research in different contexts and through different media  *       demonstrate intellectual integrity and an understanding of the ethics of scholarship.    With these attributes, developed in the formal curriculum and tested through academic assessment, graduates will be building towards having the knowledge, skills and experience to undertake independent advanced research in linguistics.  In the programme students will develop some high-level transferable skills for language-related fields, including language and social policy, marketing, and speech technology.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI005F"},"VI00Y3":{"i":"VI00Y3","entryRequirements":"Admission to a Postgraduate Diploma of Arts normally requires a Bachelors degree with a major in the same discipline. Before enrolment, a candidate shall have completed a degree at Victoria University or, at the discretion of the Associate Dean (Students","strategicPurposeStatement":"Postgraduate Diploma of Arts graduates will have advanced knowledge of a specific humanities and social sciences subject. They will be able to engage with the relevant literature critically and creatively and will be able to communicate this knowledge effectively.","graduateProfile":"NA","educationPathway":"NA","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI00Y3"},"CN0275":{"i":"CN0275","entryRequirements":"An approved Bachelor's degree or equivalent.","strategicPurposeStatement":"Graduates will have engaged in self-directed learning, demonstrating intellectual curiosity, critical thinking, and the ability to apply psychological knowledge. They will demonstrate advanced understanding of key psychological concepts, theories, and research. Graduates can critically evaluate scientific literature to inform psychological understanding and evidence-based reasoning. They demonstrate ethical and culturally responsive thinking relevant to psychological knowledge and practice. Graduates communicate psychological ideas and findings clearly and effectively in written formats suited to academic and applied audiences. They demonstrate bicultural competence and uphold obligations under Te Tiriti o Waitangi in psychology-relevant contexts.","graduateProfile":"A range of assessments will be used including written assignments, quizzes, presentations, and reflections.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0275"},"CN0152":{"i":"CN0152","entryRequirements":"A New Zealand university entrance qualification.","strategicPurposeStatement":"Students graduating from the BSW will have developed their knowledge of social policy and the organisation of national and local social services, their appreciation of discrimination and structural inequalities in society, and their proven ability to work appropriately in the practice situations experienced during their two years in the limited entry programme.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0152"},"CN0127":{"i":"CN0127","entryRequirements":"An approved Bachelor's degree.","strategicPurposeStatement":"Graduates will have advanced knowledge and understanding of current research in policy and governance. They will have the skills necessary to understand theoretical and practical problems in policy analysis and the challenges of governance in sub-national, national, not for profit, third sector and international contexts. They will have carried out a substantial piece of independent research so will have expertise in the formulation of research questions, data collection and analysis, case study analysis and hypothesis testing. They will be excellent communicators, having been trained to produce cogent and well-structured research reports, having experienced direct interaction with senior professional mentors, field work in Wellington and the regions and through problem-solving in the core course work and teaching.","graduateProfile":"NA","educationPathway":"NA","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0127"},"OO0032":{"i":"OO0032","entryRequirements":"A candidate must normally be a graduate of the University of Otago, with a Master of Laws degree conferred at least five years before candidature.","strategicPurposeStatement":"Graduates will have demonstrated special excellence in published contributions in the history, philosophy, exposition or criticism of law.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0032"},"MY0140":{"i":"MY0140","entryRequirements":". Admission to the Postgraduate Diploma in Counselling and Guidance Studies requires that the candidate:  (a) meet the University admission requirements as specified; and shall have:  (b) been awarded or qualified for a Bachelor's degree in a relevant discipline, or equivalent.","strategicPurposeStatement":"Graduates will be able to:  Critically engage with and evaluate highly specialised knowledge at the forefront of Counselling and Guidance principles, research, policy, theory and practice with particular reference to Maori approaches. Critically reflect on the significance of Te Tiriti o Waitangi for Counselling and Guidance in the unique context of Aotearoa NZ. Critically examine how issues of culture, equity, diversity, social justice and power impact Counselling and Guidance principles and practice. Critically apply Counselling and Guidance theories and approaches to case studies","graduateProfile":"Assessments reflect a mixture of presentations and written assignments, such as reports, essays and reflections.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0140"},"VI001G":{"i":"VI001G","entryRequirements":"An appropriate bachelors degree with at least a B- average and some background in economics, either professional or academic or both, as well as suitable quantitative skills.","strategicPurposeStatement":"Graduates will have an economic toolbox that they can apply to real-world problems. Graduates will be able to make sound judgments in applying economic concepts and quantitative techniques using regional, national and global perspectives. They will be able to draw on the applied research and academic literature in specialised fields of study in applied economics to undertake applied economic research in a professional context and communicate this in ways appropriate for a range of stakeholders. They will be qualified to work at an advanced level in government departments and agencies, state-owned enterprises, banks, and other private companies and consultancies in New Zealand, as well as internationally in organisations such as the Asian Development Bank, World Bank, IMF, the International Labour Organisation, and the United Nations Development Bank.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI001G"},"MY0228":{"i":"MY0228","entryRequirements":"Masters or Doctoral degree specialising in Psychology. Candidates must be employed in psychologically-based practice, have arranged for approved supervision in the field, and meet the requirements of good character and reputation for registration.","strategicPurposeStatement":"Graduates will have a detailed knowledge of psychological practice and will be able to demonstrate the core competencies required by the New Zealand Psychologists Board for registration in the general scope of practice.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0228"},"AK3913":{"i":"AK3913","entryRequirements":"An applicant must have completed the Bachelor of Sport and Recreation with a B+ grade average or higher in papers at level 7, or equivalent.","strategicPurposeStatement":"BSR(Hons) graduates will have an advanced knowledge in the area of Sport and Recreation, combined with knowledge of the fundamental contribution of research to this discipline. The BSR(Hons) will provide a foundation for multiple careers in the field of Sport and Recreation as well as a platform for further postgraduate education and doctoral research.","graduateProfile":"NA","educationPathway":"NA","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK3913"},"LI6541":{"i":"LI6541","entryRequirements":"Entry is by completion of an undergraduate degree in a related area of study with a B average at 300 level. If students perform well in the Postgraduate Diploma in Parks, Recreation and Tourism, then they will be equipped to continue to study at the Masters level.","strategicPurposeStatement":"Graduates of this programme will have a coherent understanding of parks, recreation and tourism. Graduates will be able to contribute to knowledge, critically evaluate information and communicate effectively. They will have quantitative or qualitative analytic skills, or both, that will allow them to solve a range of both theoretical and practical problems.","developedBy":"Lincoln University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=LI6541"},"AK1064":{"i":"AK1064","entryRequirements":"A relevant bachelor's degree","strategicPurposeStatement":"PgCertLC graduates will have critical knowledge and understanding in their chosen areas of focus in Applied Linguistics, which may include language analysis, language and literacy education, multilingualism and culture, and translation and interpreting. Graduates will also have critical knowledge about the relationship between language and culture. They will be critical and reflective.","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1064"},"CN0136":{"i":"CN0136","entryRequirements":"An appropriate bachelor's degree plus relevant undergraduate courses or practice experience or a qualifying programme.","strategicPurposeStatement":"Graduates are prepared for professional Social work practice with clinical skills & enhanced ability to problem solve; integrated theoretical & skills-based learning experience to work reflectively and confidently in Social work settings and to initiate & undertake research.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0136"},"WI0152":{"i":"WI0152","entryRequirements":"Bachelors degree or equivalent, & normally a Postgraduate Diploma in Second Language Teaching or equivalent","strategicPurposeStatement":"Graduates will have advanced knowledge of the application of linguistic theories, principles and concepts to the examination of practical issues including, but not limited to, research methodologies in applied linguistics, first and second language acquisition, cross-cultural approaches to learning and teaching, language teaching and assessment, language policy and planning at national and institutional levels, the analysis of discourse, the development of (electronic) literacy, and computer-mediated learning. They will have the ability to critically evaluate current scholarship in the discipline of applied linguistics, and to develop lines of argument and make sound academic judgements in accordance with basic theories and concepts of applied linguistics.","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0152"},"CN0272":{"i":"CN0272","strategicPurposeStatement":"Graduates will be able to engage in self-directed learning, show intellectual independence, analytic rigour, and the ability to apply psychological knowledge in diverse contexts. They will demonstrate advanced knowledge of psychological concepts, theories, and research. Graduates will be able to critically evaluate and synthesise scientific literature to support evidence-based conclusions and research questions. They will demonstrate ethical and culturally responsive practice across all stages of the research process. Graduates will be able to design, conduct, and analyse independent research under supervision. They can communicate research findings and psychological knowledge effectively to academic, professional, and community audiences through both written and visual formats. They will demonstrate bicultural competence and uphold obligations under Te Tiriti o Waitangi.","graduateProfile":"A range of assessments will be used including supervised research projects, written assignments, quizzes, presentations, and reflections.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0272"},"AU0261":{"i":"AU0261","entryRequirements":"Bachelor's degree or equivalent combination of tertiary study and professional qualification and/or experience. Native English speakers need an A grade in their foreign language, non-native English speakers need an IELTS score of 7.5 in the oral section and to pass an aptitude test.","strategicPurposeStatement":"PGCertAdvInterp graduates will be skilled in consecutive interpreting, enabling them to work at a fully professional level in legal, health and business settings.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU0261"},"OO0226":{"i":"OO0226","entryRequirements":"Bachelor of Physical Education degree or equivalent qualification","strategicPurposeStatement":"This diploma provides study, practical training and an introduction to research in designated areas of physical education. Recipients can proceed to further postgraduate study.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0226"},"AU5626":{"i":"AU5626","entryRequirements":"A New Zealand university entrance qualification or an approved alternative. Selection criteria apply.","strategicPurposeStatement":"Graduates will be proficient in a range of contemporary design methodologies and technologies, and be able to apply design thinking and practice to create new products, services and systems on behalf of industry, society and the economy. They will be creative, entrepreneurial practitioners able to pursue personal professional goals and postgraduate study.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5626"},"WI0055":{"i":"WI0055","entryRequirements":"BSocSc degree or equivalent. Those students who have an honours degree in a relevant field, may take 120 credits to complete the MSocSc.","strategicPurposeStatement":"Graduates will have a detailed and advanced knowledge of at least one Social Sciences subject. They will have the opportunity to  develop critical thinking skills, oral and communications skills, self-directed learning skills and more specific skills relevant to their subject of choice.","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0055"},"AK1332":{"i":"AK1332","entryRequirements":"An applicant must have completed a bachelor's degree or an equivalent qualification, with a B grade average or higher in the level 7 papers. An interview may be required.","strategicPurposeStatement":"MSI graduates will be able to identify, enable, and implement a social innovation framework for responding to complex societal issues. They will have developed strong interpersonal and networking skills, as well as ability in the effective use of a range of approaches and tools, including emerging technologies. They will have knowledge and capabilities to practise professionally in this field and may progress to further postgraduate study.","graduateProfile":"NA","educationPathway":"NA","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1332"},"WI1029":{"i":"WI1029","entryRequirements":"Candidates for the Postgraduate Diploma would normally have qualified for the award of a Bachelors Degree or equivalent.","strategicPurposeStatement":"Graduates of the Postgraduate Diploma of Professional Practice in Social and Community Services will be well prepared for further postgraduate studies in social work, health and other related areas or be well placed to respond to the needs of the community.","graduateProfile":"Examination or internal assessment.","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI1029"},"VI00F3":{"i":"VI00F3","entryRequirements":"Bachelor's degree with 1st or 2nd class honours or extensive appropriate experience","strategicPurposeStatement":"Graduates will have built on their personal disciplinary background to develop a coherent programme in their areas of interest relating to New Zealand.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI00F3"},"AK3920":{"i":"AK3920","entryRequirements":"Graduate Diploma in Psychotherapy Studies or equivalent. Personal qualities that show suitability for this programme. An applicant may be required to attend selection interviews. References, police check","strategicPurposeStatement":"Master of Psychotherapy graduates will have advanced knowledge and understanding in the field of psychotherapy to help improve the efficiency, effectiveness and quality of the profession and better meet consumer needs. They will be critical and reflective, with strong applied research capability. They will have demonstrated the ability to engage in a sustained period of research, and may progress to further study at doctoral level.","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK3920"},"LI6626":{"i":"LI6626","entryRequirements":"Entry is by completion of an undergraduate degree with a B average at 300 level.","strategicPurposeStatement":"Postgraduate Certificate in International Rural Development graduates will be able to contribute to knowledge, critically evaluate information and communicate effectively. They will be able to solve a range of both theoretical and practical problems and will have acquired the ability to work independently and with groups.  Graduates will have an understanding of development processes, their application and their implications, particularly as they relate to areas of contextual focus (Agribusiness, Economics, Finance, Environmental Management, Tourism and Research Methods). Graduates will be equipped with the knowledge and skills required to address problems of poverty and sustainable development in rural communities through development policies, intervention strategies and institutional innovations.","developedBy":"Lincoln University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=LI6626"},"AU4098":{"i":"AU4098","entryRequirements":"Bachelor's degree or approved equivalent, competence in one of the languages available for the qualification and IELTS score of at least 7 for students from a non-English speaking background","strategicPurposeStatement":"PGDipTranslationStud graduates will have a strong academic and theoretical grounding and practical training in translation enabling them to pursue employment across a wide range of careers.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU4098"},"VI002V":{"i":"VI002V","entryRequirements":"A bachelor's degree with at least a B average, or equivalent.","strategicPurposeStatement":"Graduates will have knowledge of the role of trade in society and its legal rules and economic rationales; an awareness of the social, economic, political and cultural context in which international trade operates; and an appreciation of the nature and contribution of different perspectives on international trade and related theories including customary laws of Maori and Pacific peoples.  Students will be able to analyse problems, contribute to relevant policy discussion and engage with a diversity of perspectives relevant to international trade.  Graduates will enhance their employment prospects in relevant areas of government or business. Graduates may be able to continue to the Master of International Trade (VI002R).","graduateProfile":"NA","educationPathway":"NA","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI002V"},"MY3254":{"i":"MY3254","entryRequirements":"Bachelor of Arts or equivalent.","strategicPurposeStatement":"Postgraduate Certificate in Arts graduates will have advanced knowledge in one humanities or social science discipline. They will have well-developed skills in critical thinking, problem solving, and communication.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY3254"},"CN0176":{"i":"CN0176","entryRequirements":"An approved Bachelor's degree","strategicPurposeStatement":"Graduates will be knowledgeable and skilled in analyzing issues around the European Union and its role on the Asia-Pacific region and the wider world from a range of disciplinary perspectives. They will have the appropriate attitudes, skills and knowledge to be employed professionally in any organisation with a related interest to Europe and European Union issues. The most important skills acquired will be the ability to learn independently and to communicate effectively.","graduateProfile":"Graduates will be knowledgeable and skilled in analyzing issues around the European Union and its role on the Asia-Pacific region and the wider world from a range of disciplinary perspectives. They will have the appropriate attitudes, skills and knowledge to be employed professionally in any organisation with a related interest to Europe and European Union issues. The most important skills acquired will be the ability to learn independently and to communicate effectively.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0176"},"VI004D":{"i":"VI004D","entryRequirements":"The interdisciplinary Postgraduate Certificate in Indigenous studies qualification will be open to social sciences, humanities, education and law graduates, as well as graduates with relevant backgrounds and interests from other disciplines. A Bachelor's degree in a relevant learning area with a B grade average will be required.  In some cases, it may be possible for students to have prior non-credentialed learning recognised for the purposes of admission to or credit towards a course or the programme (RPL credit).","strategicPurposeStatement":"Graduates will have the critical thinking, analytical and communication skills necessary to make a culturally appropriate and significant contribution to contemporary and traditional Maori, Pacific and Indigenous theories, issues and development. They will be equipped for work in the public and private sectors, particularly in roles that revolve around Maori, Pacific or Indigenous people and communities.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI004D"},"AU5573":{"i":"AU5573","entryRequirements":"In order to be admitted to this postgraduate diploma, a student needs to have been enrolled in the Degree of Master of Conflict and Terrorism Studies and  passed at least 30 points for that degree. Further information is available from www.auckland.ac.nz","strategicPurposeStatement":"Graduates will have advanced knowledge and skills in the study of conflict and terrorism at both the inter- and intra-state level, and will be practiced in engaging in high-level analysis and critique of these.","graduateProfile":"NA","educationPathway":"NA","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5573"},"AK1074":{"i":"AK1074","entryRequirements":"Bachelor of Arts in Criminology and Criminal Justice or an equivalent qualification.","strategicPurposeStatement":"PgDipCrimCJ graduates will have advanced knowledge and understanding of Criminology and Criminal Justice. They will be able to engage in research in the area, taking an analytical, critical and reflective approach and be prepared for further postgraduate study.","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1074"},"MY3633":{"i":"MY3633","entryRequirements":"Relevant Master's degree in Social Work with First Class or Second Class Division I Honours, or the equivalent.","strategicPurposeStatement":"Highest level of qualification available in social work. The DSW provides a high-level professional development pathway to develop as advanced practitioners, practice leaders, specialist practitioners, managers and advisors as well as social work trainers and educators.","graduateProfile":"Highest level of qualification available in social work. The DSW provides a high-level professional development pathway to develop as advanced practitioners, practice leaders, specialist practitioners, managers and advisors as well as social work trainers and educators.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY3633"},"MY0434":{"i":"MY0434","entryRequirements":"A relevant Bachelor's degree plus the equivalent of at least two years of full-time relevant professional experience or scholarly work in conjunction with extensive professional experience and standing in leadership, managerial and planning positions in government or non-government security agencies.","strategicPurposeStatement":"Graduates will demonstrate advanced knowledge of contemporary international security theory and practice; advanced research or planning skills; and competency to apply that knowledge in operations.","graduateProfile":"Not provided","educationPathway":"Not provided","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0434"},"AU5567":{"i":"AU5567","entryRequirements":"A bachelors degree with at least 60 points in social science subjects from a New Zealand University or an equivalent qualification, or an approved relevant qualification and at least two years of relevant work experience.","strategicPurposeStatement":"Graduates of the PGCertSCL will have specialised sector leadership knowledge and will be equipped with the appropriate skills required to apply that knowledge in their chosen specialist field of practice. These graduates will fill a demand for these knowledge, skills, and dispositions as identified by the community and social service, not-for-profit and social enterprise sectors in Aotearoa New Zealand and overseas. They will be critical, reflective leaders able to pursue both personal professional goals and further postgraduate study.","graduateProfile":"NA","educationPathway":"NA","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5567"},"HB3858":{"i":"HB3858","entryRequirements":"Applicants in this category will have evidence of: i) a minimum of a B+ average in Year 3 of the TMM Bachelor of Arts(Maori) OR ii) a Bachelor's degree in a relevant1 area of study with a B pass or above in the degree major OR iii) the equivalent of a Bachelor's degree such as an extended programme of learning to the equivalent of NZQA Level 7 AND For both of the above (ii) and (iii) a level of te reo Maori equivalent to a B+ average in Year 3 of the TMM Bachelor of Arts(Maori.)","strategicPurposeStatement":"The programme develops the knowledge gained in the three-year Bachelor of Arts (Maori) degree programme and provides a pathway to a wide range of professions which require in-depth knowledge of the Maori language, including research and those issues affecting Maori society, both historical and contemporary.","graduateProfile":"To understand and appreciate Maori language in its variety of oral and written forms; express themselves in the Maori language in a variety of oral and written forms; to think critically and be able to process information for one's own development; to express sound academic ideas; to express their academic thinking in the Maori language; to express themselves freely within appropriate protocols; to be able to actively participate with ease and confidence in a variety of Maori social, ritual and cultural situations and to be able to take a lead role if necessary; to gain an increased level of independence of thought, action and opportunity through the acquisition of research skills and academic discipline gained through participation in tertiary level study; to be sufficiently equipped with knowledge of Maori language and culture to be able to provide sound advice and guidance on things Maori as part of one's chosen career and one's community; and to be sufficiently equipped with the skills of both bilingualism and biculturalism in order to enhance employment opportunities for themselves.","educationPathway":"Staircasing from certificate in Maori studies to BA Maori Studies.","developedBy":"Eastern Institute of Technology","qualityAssuredBy":"New Zealand Qualifications Authority","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=HB3858"},"VI004S":{"i":"VI004S","entryRequirements":"The Postgraduate Diploma in Health Psychology requires a Bachelor of Health in Health Psychology, a Bachelor of Science in Psychology, a Bachelor of Arts in Psychology, a Graduate Diploma in Health (Health Psychology specialisation), or a Graduate Diploma in Psychology.","strategicPurposeStatement":"Employment options for graduates of the Postgraduate Diploma in Health Psychology include health promotion, health policy, public health, and other mental health and wellbeing roles in both district health boards and non-governmental agencies.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI004S"},"CN0335":{"i":"CN0335","entryRequirements":"An approved Bachelor's degree or equivalent.","strategicPurposeStatement":"Students who successfully complete the certificate will have gained advanced knowledge and skills in criminal justice, enhanced employment options and an upgrade pathway for admission to the Master of Criminal Justice. They will have gained skills in locating, evaluating, and synthesising information from a range of primary and secondary sources relevant to a research topic and the ability to analyse critically key issues of principle and policy in relation to criminal justice systems and their operation in practice.","graduateProfile":"A range of assessments will be used including coursework, tests and formal examinations","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0335"},"AU0012":{"i":"AU0012","entryRequirements":"Students must have already completed the requirements for the BA","strategicPurposeStatement":"BA(Hons) graduates will have advanced knowledge and understanding of the content and the discipline of a subject or specialization in the Faculty. They will be able to engage in research in the area analytically, critically and reflectively.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU0012"},"CN0155":{"i":"CN0155","entryRequirements":"An approved Bachelor's degree.","strategicPurposeStatement":"Graduates will have an advanced capability in te reo Maori that will enable them to be employed professionally or to work independently to produce high quality works in te reo Maori and/or take a leadership role in language revitalisation strategies. They will be able to learn independently and communicate effectively, as well as learn collaboratively within a strong peer network of reo Maori speakers.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0155"},"AK1044":{"i":"AK1044","entryRequirements":"(a) a Bachelor of Laws or (b) a Bachelor of Laws (Honours) or equivalent.","strategicPurposeStatement":"The LLM provides postgraduate study and professional development for lawyers whether they are practising or planning to practise in the legal profession, industry or the public sector. The programme is aimed at those who have already completed a law degree and wish to gain advanced legal knowledge and develop their research skills in areas of law relating to crime, finance, banking, taxation, intellectual property, corporate governance, securities, competition, employment, property and resource management.","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1044"},"MY0219":{"i":"MY0219","entryRequirements":"A relevant bachelor's degree and proficiency in the Maori language.","strategicPurposeStatement":"Holders will have an advanced level of proficiency in Maori language.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0219"},"WI0072":{"i":"WI0072","entryRequirements":"A graduate of the University of Waikato or the University of New Zealand","strategicPurposeStatement":"Graduates have knowledge and skills in the field of literature that are superior in both knowledge and application to that of their undergraduate and post-graduate contemporaries. They are undisputed national and/or international experts and leaders in their specialist area.","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0072"},"OO0002":{"i":"OO0002","entryRequirements":"A Bachelor of Arts degree with an average grade of at least B+ in the final year of study.","strategicPurposeStatement":"Graduates of this degree programme will have acquired in-depth knowledge of a chosen humanities subject or subjects, and will have been introduced to research through the preparation of a dissertation. Graduates will be able to pursue professional goals and undertake further postgraduate study.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0002"},"LI4532":{"i":"LI4532","entryRequirements":"Entry to the programme will be limited to students with a prior undergraduate qualification in a related discipline. Students will be expected to have achieved at least a 'B+' average in 300-level courses in their undergraduate qualification","graduateProfile":"Graduates will possess an understanding of the complexity of the sport and recreation sector, and how elements such as political systems, policy bodies, the world and/or local economy and environmental change can affect individual business decisions and long term planning within the sector. They will have quantitative or qualitative analytic skills, or both, that will allow them to solve a range of both theoretical and practical problems. Graduates will be equipped with advanced research skills and capable of high-level research. High achieving graduates will be equipped to continue to PhD study.","developedBy":"Lincoln University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=LI4532"},"CN0708":{"i":"CN0708","entryRequirements":"A degree of the University of New Zealand or the University of Canterbury.","strategicPurposeStatement":"LittD graduates will have made significant original contributions of published original research to letters.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0708"},"AU0033":{"i":"AU0033","entryRequirements":"A New Zealand university entrance qualification or an approved alternative. Must meet entry requirements of each component degree. Selection criteria apply.","strategicPurposeStatement":"BProp/LLB(Hons) graduates will demonstrate knowledge and understanding of the content and application ofelements of both Law and Property disciplines with additional enhanced research and writing skills within the law component.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU0033"},"OO0556":{"i":"OO0556","entryRequirements":"Internal assessment, examinations.","strategicPurposeStatement":"Graduates will be equipped with exceptional industry-driven knowledge and skills relevant to clinical practice in neuropsychology, neuroscience and rehabilitation.","graduateProfile":"Available to practising psychologists, working at least 0.6FTE in an appropriate clinical setting, who have completed the requirements for registration with the New Zealand Psychologists Board under any scope of practice. Applicants will hold a Masters or Doctoral degree.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0556"},"VI001S":{"i":"VI001S","strategicPurposeStatement":"Graduates will have advanced knowledge of politics in New Zealand and other countries, including theoretical approaches to the study of politics. They will be able to conduct independent research and will be capable of sophisticated and rigorous critical analysis of evidence and arguments. They will be well qualified for careers in public affairs, including politics, the civil service, think tanks, lobbying and civil society organisations. Some graduates may be able to continue to doctoral studies in political science.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI001S"},"AU5772":{"i":"AU5772","entryRequirements":"ompleted a relevant Bachelors Honours degree with a minimum GPA or a relevant Bachelors Honours degree and passed 60 points towards the Postgraduate Certificate in Intellectual Property or a relevant Bachelors Honours degree with a minimum GPA and relevant professional experience, or a Bachelor of Laws or or Bachelor of Laws (Honours) with a minimum GPA.","strategicPurposeStatement":"Master of Intellectual Property graduates will have attained the knowledge, values and skills related to intellectual property law that will help enable them to practice as a patent attorney.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5772"},"MY0264":{"i":"MY0264","entryRequirements":"Degree or Admission with Equivalent Status","strategicPurposeStatement":"To train sports managers and coaches","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0264"},"OO0331":{"i":"OO0331","entryRequirements":"Degree in Theology or alternative qualifications or experience","strategicPurposeStatement":"This course is designed for priests and ministers in churches and other agencies who seek advanced professional education.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0331"},"AU5511":{"i":"AU5511","entryRequirements":"A Bachelor of Social Work or equivalent.","strategicPurposeStatement":"PGDipSW graduates will know and understand the principles, concepts and ideas of advanced practice in professional social work in general and specialised contexts. They will be critical, reflective practitioners able to pursue personal professional goals and pursue further postgraduate study.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5511"},"VI00K3":{"i":"VI00K3","entryRequirements":"New Zealand Bachelor's degree and two years of relevant work experience or extensive practical, professional or scholarly experience.","strategicPurposeStatement":"Graduates will have mastered a multi-disciplinary approach to public policy analysis and public sector management issues, and extended their technical and managerial skills.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI00K3"},"OO0076":{"i":"OO0076","entryRequirements":"Bachelor's degree or acceptable alternative.  Preferred qualificaiton is Bachelor of Physical Education","strategicPurposeStatement":"This degree involves supervised research in a chosen area. Graduates will have advanced knowledge in the field, and the ability to study independently, and to carry out original research to internationally recognised standards.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0076"},"CN0194":{"i":"CN0194","entryRequirements":"A Bachelor's degree with a major or equivalent in Maori and Indigenous Studies or Te Reo Maori.","strategicPurposeStatement":"Graduates with some knowledge of the field will have a grounding in critical theory and an advanced knowledge and research-based understanding of a selection of topics in the subject area. Graduates will be able to think critically, with a research-based understanding of the subjects addressed.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0194"},"VI00V1":{"i":"VI00V1","entryRequirements":"A bachelor's honours degree, or other approved qualification with appropriate experience.","strategicPurposeStatement":"Graduates will be skilled in communication, acquiring and organising information and using appropriate information technology. They will apply their knowledge of relevant principles and theories to senior professional information management roles in corporate information management, policy analysis, public relations, database management, web and intranet content management, electronic publishing, public librarianship, academic librarianship, school libraries, systems sales, systems training. Alternatively they may work independently as information brokers, designers, and trainers. Graduates with specialisations in library science or archives and records management will also have in-depth knowledge of appropriate theoretical frameworks and best practice in these fields.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI00V1"},"AU4044":{"i":"AU4044","strategicPurposeStatement":"The Master of Theology degree enables students with previous qualifications in theology to focus on a particular area of theological study and to develop knowledge and skills in that area","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU4044"},"CN0107":{"i":"CN0107","entryRequirements":"An approved Bachelor's degree.","strategicPurposeStatement":"Graduates will have advanced knowledge and understanding of current research in international relations and current professional practice in diplomacy and related fields. They will have the skills necessary to understand theoretical and practical problems in international relations and to appreciate the connections between the principles and practice of diplomacy. Graduates will also have carried out a substantial piece of independent research so will have expertise in the formulation of research questions, data collection and analysis, case study analysis and hypothesis testing. They will be excellent communicators, having been trained to produce cogent and well-structured research reports and having experienced direct interaction with senior figures in politics and policy on the field trip and in the core course.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0107"},"VI002H":{"i":"VI002H","strategicPurposeStatement":"Graduates will have knowledge of the interdisciplinary theoretical and comparative literature on human migration, which they will use to analyse practical and theoretical problems. They will communicate their ideas effectively in writing and orally. Their knowledge will inform their roles in public sector agencies and non-governmental bodies that work on human migration. Some graduates will be able to continue to the Postgraduate Diploma in Migration Studies (VI002G) or the Master of Migration Studies (VI001Z). The PGCertMigS also acts as an exit qualification for the PGDipMigS and MMigs.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI002H"},"VI0092":{"i":"VI0092","entryRequirements":"A degree of Victoria University of Wellington awarded at least 5 years prior to candidature; or other acceptable preparation.","strategicPurposeStatement":"A degree intended to recognise major achievements in a field of the humanities or social sciences.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI0092"},"OO0003":{"i":"OO0003","entryRequirements":"A Bachelor of Arts degree or equivalent.","strategicPurposeStatement":"This diploma programme involves advanced coursework and research in a chosen arts or social science subject. Recipients of the diploma are capable of self-directed learning and intellectual independence, and can proceed to further postgraduate study.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0003"},"MY0406":{"i":"MY0406","entryRequirements":"Bachelor's degree or equivalent.","strategicPurposeStatement":"Graduates will have advanced knowledge in a selected discipline which may be different from prior undergraduate studies. They will be able to create new knowledge, critically evaluate information and communicate effectively, and be prepared for doctoral studies.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0406"},"WI0059":{"i":"WI0059","entryRequirements":"LLB degree or equivalent.","strategicPurposeStatement":"Graduates will have knowledge and skills in law that are superior  to that of their undergraduate contemporaries. They have particularly deep and insightful understanding of law in specialist areas. They have an awareness of the law in context, the international comparative framework, and cultural dimensions.","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0059"},"VI002X":{"i":"VI002X","entryRequirements":"A bachelor's degree or equivalent, normally with a B+ average grade or better in the relevant coursework.","strategicPurposeStatement":"Graduates will have an understanding of theory and practice in the museum and heritage sector. Graduates may be able to continue to the Postgraduate Diploma in Museum and Heritage Practice (VI002W) or the Master of Museum and Heritage Practice (VI002T).","graduateProfile":"NA","educationPathway":"NA","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI002X"},"WI0071":{"i":"WI0071","entryRequirements":"An Honours degree or Masters degree with at least 2nd class honours (1st division) or distinction, or equivalent.","strategicPurposeStatement":"Graduates will be independent scholars with the ability to conduct original research to an internationally recognised standard in their chosen field of study, and communicate effectively to different audiences.","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0071"},"AK2016":{"i":"AK2016","entryRequirements":"A bachelor's degree, or a relevant professional qualification or experience approved by the dean (or representative) to be equivalent to a bachelor's degree.","strategicPurposeStatement":"PgDipGast graduates will have advanced knowledge and understanding of gastronomy. They will be able to engage in research in the area, taking an analytical, critical and reflective approach and be prepared for further postgraduate study.","graduateProfile":"NA","educationPathway":"NA","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK2016"},"LI0639":{"i":"LI0639","entryRequirements":"A relevant bachelors degree.","strategicPurposeStatement":"Graduates of this programme will gain an advanced, integrated, social science knowledge of a theme or themes related to society at an advanced level.","developedBy":"Lincoln University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=LI0639"},"AU5765":{"i":"AU5765","entryRequirements":"Three years relevant professional experience, and either completed a relevant Bachelors degree or equivalent with a minimum GPA, or passed 60 points in the Postgraduate Certificate in Professional Supervision or Psotgraduate Diploma in Professional Supervision with a minimum GPA. Must be currently employed or volunteering in an appropriate professional context.","strategicPurposeStatement":"MProfSup graduates will have mastery of clinical skills in professional supervision as well as advanced knowledge of the scholarship of the field. They will have a demonstrated ability to engage in independent research in the field that synthesises appropriate theory, research methodology and methods, and data. They will be prepared to pursue doctoral scholarship.","graduateProfile":"Written assignments, individual and group projects, case analyses, and presentations.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5765"},"AU5678":{"i":"AU5678","entryRequirements":"Completed the requirements for a relevant Bachelors degree or with a major in Psychology, or a Graduate Diploma  in a relevant subject  with a minimum Grade Point Average (GPA).","strategicPurposeStatement":"MOrgPsych graduates will have developed an advanced set of research-informed knowledge, skills, abilities in Organisational Psychology and the ability to apply these to new contexts in organisational settings. Graduates will be well-prepared for a range of specialist employment opportunities and careers in the broad area of Organisational Psychology.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5678"},"WI1022":{"i":"WI1022","entryRequirements":"Candidates for the Postgraduate Certificate would normally have qualified for the award of a Bachelors Degree or equivalent.","strategicPurposeStatement":"This qualification aims to provide the first new postgraduate qualification in Indigenous Data Sovereignty and Analytics for professionals in public, private and not-for-profit sectors in Aotearoa. Its overarching goals are to: prepare graduates with solid foundations in indigenous data sovereignty who can adopt an indigenous lens to analyse and interpret Indigenous data. Students of this qualification will be able to critically appraise colonial approaches to data governance (e.g. deficit patterning of Indigenous statistics) and grasp how indigenous data sovereignty and indigenous data governance can be mechanisms to disrupt these.","graduateProfile":"Examination or internal assessment","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI1022"},"LI6540":{"i":"LI6540","entryRequirements":"Entry is by completion of an undergraduate degree in a related area of study with a B average at 300 level. If students perform well in the Postgraduate Certificate in Parks, Recreation and Tourism, then they will be equipped to continue to study at the Diploma or Masters level.","strategicPurposeStatement":"Graduates of the PG Cert PRT programme will have a sound grounding in the theory and practice of Parks, Recreation and Tourism. They will have knowledge of the broader political, socio-cultural, economic and institutional contexts in which it is conducted to understand the complexity of Parks, Recreation and Tourism issues and practice. They will also have developed skills in critical analysis, evaluation, problem-solving and communication that are relevant to the many fields of Parks, Recreation and Tourism.","developedBy":"Lincoln University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=LI6540"},"OO0011":{"i":"OO0011","entryRequirements":"A candidate must normally be a graduate of the University of Otago, with a master's degree conferred at least five years before candidature.","strategicPurposeStatement":"Graduates will have demonstrated special excellence in original linguistic, literary, social or historical knowledge","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0011"},"MY0717":{"i":"MY0717","entryRequirements":"A relevant bachelors degree.","strategicPurposeStatement":"Holders will have advanced knowledge in issues relating to development studies and be able to apply this knowledge in relevant contexts.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0717"},"VI00V7":{"i":"VI00V7","entryRequirements":"A bachelor's degree or other approved qualification.","strategicPurposeStatement":"Graduates will use their communication skills and knowledge of relevant principles and theories in professional information management roles. Graduates specialising in library science or archives and records management will be able to apply appropriate theoretical frameworks and best practice in these fields. They may continue to the Master of Information Studies (VI00V1).","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI00V7"},"WI0804":{"i":"WI0804","entryRequirements":"Master of Applied Psychology or equivalent.","strategicPurposeStatement":"The Postgraduate Diploma in the Practice of Psychology is designed to meet the requirements for registration as a psychologist under the Health Practitioners Competency Assurance Act. Graduates of the Organisational Psychology stream will have developed practical skills in applying organisational psychology techniques, such as job analyses, test validation, training needs analysis and evaluation, career counselling and development, organisation development and workplace well-being. Graduates of the Applied Behaviour Analysis stream will have developed practical skills in applying behavioural principles to a range of behaviour problems in their area of specialty. Graduates of the Community Psychology stream will have developed practical skills in applying the principles and concepts of Community Psychology to a range of situations within their area of specialty. They will also be familiar with the evaluation of social service programmes, including needs assessments, formative evaluation, process evaluation and outcome evaluation, and major research methodologies relevant to applied community research, including surveys and interview studies, with a particular emphasis on qualitative research.","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0804"},"AU5615":{"i":"AU5615","entryRequirements":"A Bachelor of Arts(Honours) or Bachelor of Arts, or the equivalent, and a minimum GPA, and a minimum level of competence in one of the languages offered for the degree. Non-native English speakers must meet minimum English language requirements.","strategicPurposeStatement":"MTran graduates will gain an advanced understanding of principles, concepts and ideas that define translation and inform best practice. They will be critical and reflective practitioners equipped with a solid ethical understanding. They will be able to pursue personal professional goals with scope to consider a variety of career paths as well as further postgraduate study in future.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5615"},"AU5508":{"i":"AU5508","entryRequirements":"A bachelor's degree or postgraduate qualification in education, counselling, nursing, social work, or similar; and at least three years experience in the practice of an appropriate profession.","strategicPurposeStatement":"Master of Counselling graduates will practise with a high level of competence in a diverse range of professional environments, utilising theory and research to inform their current and future practice. They will also make an effective contribution to the research environment by engaging in research practitioner dialogue and counselling-related research activities.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5508"},"WI0997":{"i":"WI0997","entryRequirements":"Bachelors degree with at least a B grade average or equivalent","strategicPurposeStatement":"The programme gives students from civil law backgrounds an opportunity to explore some of the most distinctive methods, practices and doctrines of the uniquely distinctive New Zealand common law system (including Te Ao Maori concepts).","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0997"},"CN0310":{"i":"CN0310","entryRequirements":"A New Zealand university entrance qualification, then invitation by the Dean of Law after completion of 3 years of LLB study. LLB graduates are not eligible to enrol in the Honours degree.","strategicPurposeStatement":"Graduates will have a broad, critical legal education and advanced knowledge in designated areas of law. They will have enhanced skills in legal research, including use of electronic databases and search tools, writing and advocacy and will be widely recognised for their high intellectual abilities and outstanding skills and be readily employable in the legal profession or elsewhere.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0310"},"MY1067":{"i":"MY1067","entryRequirements":"Appropriate degree or equivalent. Relevant work in a related area to whanau development within three years of application for admission.","strategicPurposeStatement":"Graduates will demonstrate an ability to communicate with confidence in written, oral and electronic forms; confidence in interacting with whanau and Maori communities, and knowledge in relation to whanau endeavours. They will have an understanding of whanau dynamics and whanau in society. Graduates will be able to discuss barriers and opportunities, will have an understanding of whanau structures, functional capacities and indicators of whanau wellbeing, and will be able to utilise research to inform whanau development practice.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY1067"},"CN0278":{"i":"CN0278","entryRequirements":"An approved Bachelor's degree or equivalent.","strategicPurposeStatement":"Advanced knowledge of psychological concepts, theories, and research; evaluation and synthesis of scientific literature to support evidence-based conclusions and research questions; ethical and culturally responsive thinking in relation to all stages of the psychological research process; critical engagement with selected stages of the psychological research process, including methodological planning and the analysis of open-source, non-human, or simulated data; written communication of research findings and psychological knowledge to academic, professional, and community audiences; implementation of Te Tiriti o Waitangi obligations in psychology; knowledge of postgraduate study pathways; employments skills, advanced research methods and statistics (for students who wish to progress to further postgraduate study).","graduateProfile":"A range of assessments will be used including written assignments, quizzes, presentations, and reflections.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0278"},"CN0855":{"i":"CN0855","entryRequirements":"An approved Bachelor's degree or equivalent.","strategicPurposeStatement":"Graduates of this programme will have developed specialist knowledge of professional supervision frameworks and practical supervision skills through theoretical study and reflective practice learning. They will understand and apply frameworks and knowledge from Te Ao Maori relevant to professional supervision. They will be able to work effectively one-to-one with individuals and in group supervision contexts across a range of professional supervision settings. Graduates will use critical thinking and evidence-informed approaches to support effective communication, problem solving, and decision-making in professional supervision contexts.","graduateProfile":"A range of assessments will be used including written assignments, presentations, case studies and portfolios.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0855"},"OO0249":{"i":"OO0249","entryRequirements":"A bachelor's or honours degree completed to an appropriate standard, or equivalent.","strategicPurposeStatement":"Graduates of this degree programme will have advanced analytical skills and knowledge of contemporary international issues.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0249"},"WI0957":{"i":"WI0957","entryRequirements":"A New Zealand university entrance qualification or equivalent.","strategicPurposeStatement":"This conjoint degree gives students the opportunity to complete the requirements of two bachelor degrees over a reduced period of time. Graduates will have knowledge and skills from both Business and Law disciplines which gives them a good grounding for careers in many areas.","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0957"},"AK1049":{"i":"AK1049","entryRequirements":"A relevant bachelor's degree with a B grade average or higher in papers at level 7 or equivalent.","strategicPurposeStatement":"MLC graduates will have advanced critical knowledge and understanding in their chosen areas of focus in Applied Linguistics, which may include the proficiency, linguistic and/or cultural knowledge of an Asia-Pacific language (or their own language/s), language analysis, language and literacy education, multilingualism and culture, and translation and interpreting. Graduates will also have advanced critical knowledge about the relationship between language and culture. They will be critical and reflective, and have demonstrated the ability to engage in a period of applied research. Some may progress to further study at doctoral level.","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1049"},"VI005W":{"i":"VI005W","entryRequirements":"The PGCert is \"open to graduates or to those who have been able to demonstrate extensive practical, professional, or scholarly experience that provides an equivalent level of preparation\".","strategicPurposeStatement":"Graduates of the PGCert in Law will gain a thorough grounding in the theory and practice of law and use their knowledge to improve the quality of their legal advice. Â Graduates will show ethical behaviour in using and advising on the law in their chosen career.","graduateProfile":"Courses incorporate a range of teaching and assessment methods such as research papers, take home exams, position papers, class participation, verbal presentations, reflective summaries, individual and group assignments.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI005W"},"VI0012":{"i":"VI0012","entryRequirements":"A degree of Victoria University including relevant prerequisites.","strategicPurposeStatement":"Postgraduate level study of a range of subjects from the fields of literature, language, arts, humanities and social sciences as listed in the BA (Hons) statute in the University Calendar.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI0012"},"VI005G":{"i":"VI005G","entryRequirements":"A Bachelor's degree in Linguistics or a related subject with an average grade of B or better.","strategicPurposeStatement":"Students in the Master of Linguistics will be part of the research culture of the Linguistics programme within the School of Linguistics and Applied Language Studies. The MLing degree will prepare graduates who:   \n\r\n*have specialised knowledge of a range of current areas of linguistic research, including those of an interdisciplinary nature   \n\r\n*have a grounding in the use of quantitative and qualitative methods for collecting and analysing linguistic data   \n\r\n*are able to make critically informed decisions about the methods appropriate for investigating different research questions   \n\r\n*are able to develop their own complex ideas related to linguistic structure and language use based on a sound understanding of relevant research   \n\r\n*communicate effectively and accurately about linguistic research in different contexts and through different media   \n\r\n*demonstrate intellectual integrity and a thorough understanding of the ethics of scholarship.      \n\n\n\r\nWith these attributes, developed in the formal curriculum and tested through academic assessment, graduates will have the knowledge, skills and experience to undertake independent advanced research in linguistics, including interdisciplinary perspectives. The programme prepares students for entry into PhD programmes in New Zealand or internationally. In addition, the programme develops in students high-level transferable skills for language-related fields, including language and social policy, marketing, and speech technology.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI005G"},"AU1006":{"i":"AU1006","entryRequirements":"MASTERS DEGREE WITH HONOURS","strategicPurposeStatement":"MLitt graduates will have presented research equivalent to one years full-time work that demonstrates advanced analytical, critical and reflective skills in the observation, synthesis and interpretation of material in one of the areas offered.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU1006"},"OO0332":{"i":"OO0332","entryRequirements":"Degree in Theology and acceptable experience in ministry, or acceptable alternative qualifications or experience","strategicPurposeStatement":"This Master's degree course is for priests and ministers in churches and other agencies who seek advanced professional education.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0332"},"VI00Y4":{"i":"VI00Y4","entryRequirements":"A degree at honours or master's level, or other postgraduate qualification, relevant to public policy studies; plus appropriate professional experience and demonstrated public sector leadership potential.","strategicPurposeStatement":"Graduates of this programme will be able to lead initiatives that address challenges, resolve problems, pursue opportunities, and promote progress in areas that are the responsibilities of governments and their agencies, using practical applications of research skills, knowledge and in-depth understanding of relevant theory and practice.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI00Y4"},"WI0052":{"i":"WI0052","entryRequirements":"BA degree or equivalent. Those students who have an honours degree in a relevant field, may take 120 credits to complete the MA.","strategicPurposeStatement":"Graduates will have a detailed and advanced knowledge of at least one Humanities subject.  They will have the opportunity to develop critical thinking skills, oral and communications skills, self-directed learning skills and more specific skills relevant to their subject(s) of choice.","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0052"},"AK1023":{"i":"AK1023","entryRequirements":"A bachelor's degree with a B average or higher in papers in level 7 or equivalent.","strategicPurposeStatement":"Graduates of the programme will understand the historical development and evolution of human rights, and understand emerging paradigms and contemporary challenges in human rights at national, regional and international levels. Graduates will learn to utilise the human rights framework in the development and evaluation of policy. They will have skills that will equip them for academic work, policy analysis, advocacy and communication roles in a range of contexts and organisations.  Graduates will have the knowledge, understanding and skills equipping them for employment in human rights advocacy and research, policy analysis, legal services, human rights education, non-governmental organisations, community development, conflict resolution, civil society organizations and international development organisations. Given that human rights have become the core language of a new politics of humanity, according to legal historian Samuel Moyn, it is anticipated that the programme will have applicability to a wide range of occupations.","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1023"},"OO0488":{"i":"OO0488","entryRequirements":"Acceptable performance in the third year of the Bachelor of Social Work programme.","strategicPurposeStatement":"Graduates of this degree programme will have a strong grounding in the core competencies expected of a professionally registered social worker in Aotearoa/New Zealand.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0488"},"CN0854":{"i":"CN0854","entryRequirements":"An approved Bachelor's degree or equivalent.","strategicPurposeStatement":"Graduates of this programme will demonstrate advanced knowledge and skills in professional supervision acquired through theoretical study and scholarly inquiry, enabling them to work effectively and collaboratively in interdisciplinary professional supervision settings. They will understand and apply frameworks and knowledge from Te Ao Maori relevant to professional supervision. They will apply critical thinking, evidence-informed decision-making, and reflective practice to contribute meaningfully to team-based environments, demonstrate leadership when appropriate, and engage in effective communication and problem-solving to support high-quality outcomes in professional supervision contexts.","graduateProfile":"A range of assessments will be used including written assignments, presentations, case studies and portfolios.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0854"},"VI004B":{"i":"VI004B","entryRequirements":"The interdisciplinary 180-point Master of Indigenous Studies qualification will be open to social sciences, humanities, education and law graduates, as well as graduates with relevant backgrounds and interests from other disciplines. A Bachelor's degree in a relevant learning area with a B grade average will be required.  In some cases, it may be possible for students to have prior non-credentialed learning recognised for the purposes of admission to or credit towards a course or the programme (RPL credit).","strategicPurposeStatement":"Graduates will have the research, thinking and communication skills necessary to make a culturally appropriate and significant contribution to contemporary and traditional Maori, Pacific and Indigenous theories, issues and development. They will be equipped for work in the public and private sectors, particularly in roles that revolve around Maori, Pacific or Indigenous people and communities.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI004B"},"AK3518":{"i":"AK3518","entryRequirements":"A masters degree with first- or second-class honours, or a Bachelors degree with first- or second-class honours, including advanced learning in research, a research project and a report on the research project.","strategicPurposeStatement":"PhD graduates will have a highly developed knowledge and understanding of their chosen field of study and will be able to contribute at an internationally recognised standard to original scholarship and research.","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK3518"},"OO0496":{"i":"OO0496","entryRequirements":"A bachelor's degree, normally with an average grade of at least B+ in the final year of study, or equivalent.","strategicPurposeStatement":"Graduates of this degree programme will understand the major sources of violent conflict and know how to research, analyse, evaluate and respond to the different dynamics of both violent and non-violent behaviour. Graduates will also understand the prerequisites and structural conditions for building sustainable peace in a range of diverse cultural settings and at different stages of the conflict cycle. They will have skills that will equip them for academic work, policy analysis and roles as reflective practitioners and a wide range of other occupations as well.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0496"},"MY0353":{"i":"MY0353","entryRequirements":"BA Hons or PGDipArts or equivalent in Creative Writing, Expressive Arts, English or approved subject; creative writing portfolio.","strategicPurposeStatement":"Graduates will have the capacity and potential to produce creative writing of a professional standard. Graduates will also have the capacity to write critical reviews and essays at an appropriate level of accomplishment, and will have an understanding of the publishing or production processes appropriate to their chosen genre(s).","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0353"},"AU5584":{"i":"AU5584","entryRequirements":"A New Zealand university entrance qualification or an approved alternative. Must meet entry requirements of each component degree. Selection criteria apply.","strategicPurposeStatement":"BGlobalSt/LLB(Hons) graduates will demonstrate knowledge and understanding of the content and application of elements of both Global Studies and Law disciplines with additional enhanced research and writing skills within the law component.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5584"},"OO0328":{"i":"OO0328","entryRequirements":"A Bachelor of Physical Education degree or equivalent.","strategicPurposeStatement":"This is a programme of advanced educational and vocational learning for experienced outdoor leaders; graduates of the programme will have a sound foundation for subsequent research study in outdoor education.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0328"},"AK1009":{"i":"AK1009","entryRequirements":"An applicant will be required to have completed Parts I and Part II for the Degree of Bachelor of Laws to a satisfactory standard before being permitted to enrol for this degree.","strategicPurposeStatement":"LLB (Hons) graduates will have a comprehensive knowledge of the NZ legal framework and its underlying concepts and principles with a particular understanding of commercial law applications. Graduates will have developed, to a high level, skills in critical and ethical analysis, problem-solving, and written and oral communication. Graduates will have demonstrated capability in planning and carrying out high quality research and will have produced a substantial piece of well written, clearly reasoned legal writing which reflects critically on the research undertaken. As well as meeting the requirements for admission as barristers and solicitors in NZ, graduates will be prepared for employment opportunities in a wide variety of occupations in commercial, non-commercial and government organisations operating both in NZ and internationally and for postgraduate study.","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1009"},"MY0435":{"i":"MY0435","entryRequirements":"A Bachelor of Arts (Developmental Studies), with a minimum B average across the 200 and 300-level majoring courses, or equivalent; or a Bachelor degree, with a minimum B average across the 200 and 300-level courses and relevant field or industry experience; or a Postgraduate Diploma in  International Development, with a minimum B average, or equivalent.","strategicPurposeStatement":"Graduates will demonstrate knowledge and skills which can be applied in developing policy and strategies, and in managing and evaluating international development programmes. They will also have the capacity to implement independent research reports in a rigorous and ethical manner and to effectively analyse and communicate findings of research. Graduates will thus be employable by a wide range of development agencies in the public, private and civil society sectors (including NGOs).","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0435"},"OO0537":{"i":"OO0537","entryRequirements":"A bachelor's degree majoring in Sport Development and Management, with an average grade of at least B in the final year of study, or equivalent.","strategicPurposeStatement":"Graduates will have a thorough understanding of sport, including its varied forms and cultures, its role, purpose and status in everyday life, and the way the sport sector is organised, administered and managed locally nationally and globally.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0537"},"CN0186":{"i":"CN0186","entryRequirements":"An approved Bachelor's degree and professional experience.","strategicPurposeStatement":"Graduates will have the appropriate attitudes, skills and knowledge to be employed professionally in a leadership role in any organisation with a related interest to the Maori sector.  They will be knowledgeable and skilled in analysing indigenous development issues and opportunities and importantly be able to create innovative and principled solutions that advance Maori interests and aspirations. They will be able to learn independently and communicate effectively.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0186"},"AK1076":{"i":"AK1076","entryRequirements":"A relevant bachelor's degree.","strategicPurposeStatement":"PgCertENMS graduates will have an advanced knowledge and understanding of new media practices in relation to a specified field of English Studies. They will demonstrate critical thinking, in depth analytical skills and intellectual independence. The programme will extend graduates' professional skills and prepare them for further study.","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1076"},"OO0324":{"i":"OO0324","entryRequirements":"A professional social services qualification and two years of relevant work experience.","strategicPurposeStatement":"Graduates of this degree programme will be prepared for senior level and specialist practice in social services, research and policy analysis.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0324"},"VI004C":{"i":"VI004C","entryRequirements":"The interdisciplinary Postgraduate Diploma in Indigenous Studies qualification will be open to social sciences, humanities, education and law graduates, as well as graduates with relevant backgrounds and interests from other disciplines. A Bachelor's degree in a relevant learning area with a B grade average will be required.  In some cases, it may be possible for students to have prior non-credentialed learning recognised for the purposes of admission to or credit towards a course or the programme (RPL credit).","strategicPurposeStatement":"Graduates will have the research, thinking and communication skills necessary to make a culturally appropriate and significant contribution to contemporary and traditional Maori, Pacific and Indigenous theories, issues and development. They will be equipped for work in the public and private sectors, particularly in roles that revolve around Maori, Pacific or Indigenous people and communities.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI004C"},"OO00505":{"i":"OO00505","strategicPurposeStatement":"This programme provides chaplains with specialised training. Holders of the certificate will be able to demonstrate the ability to integrate thought and action, integrate professional and intellectual ability, exercise independent judgement, undertake analysis, research a topic, and reflect professionally upon one's own and others' actions.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO00505"},"AU0371":{"i":"AU0371","strategicPurposeStatement":"Master of Arts graduates will have advanced knowledge and understanding of the content and the discipline of a subject or specialisation in the Faculty. They will be able to engage analytically, critically and reflectively with their chosen specialisation and will have demonstrated an ability to undertake a sustained period of research.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU0371"},"OO0514":{"i":"OO0514","entryRequirements":"A bachelor's degree or equivalent.","strategicPurposeStatement":"Graduates of this degree programme will have attained disciplinary knowledge of a range of the four main sub-fields in Politics (political theory, international relations, comparative politics and New Zealand politics); the ability to think critically with respect to the academic research in Politics; and the ability to undertake independent academic research.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0514"},"AK1101":{"i":"AK1101","entryRequirements":"Bachelor's degree with a B grade average at level 7 or equivalent.  Relevant professional experience approved by dean as equivalent to the above.","strategicPurposeStatement":"MAppPsych graduates will have advanced knowledge and applied skills in psychological science to address real-world challenges in diverse workplace settings. They will be critical thinkers, capable of designing and evaluating interventions that enhance wellbeing, leadership, and organisational outcomes. Graduates will bring culturally responsive, ethical, and collaborative approaches to their work, integrating Maori and Pasifika perspectives. They will be prepared for a wide range of roles where advanced applied psychological knowledge and research skills are valued, including in organisational development, human resources, policy analysis and programme evaluation.?","graduateProfile":"Courses employ a diverse range of assessments, including case analyses, simulation-based interventions, reflective practice portfolios, collaborative presentations, and applied research design.","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1101"},"WI0923":{"i":"WI0923","entryRequirements":"BA, BA(Hons), BSocSc, BSocSc(Hons), BSc or BSc(Hons) degree or equivalent","strategicPurposeStatement":"Graduates will have an in-depth understanding of animal behaviour, animal health and welfare, and animal-related ethical and legal matters. They will have an understanding of learning theory, which will extend to application of skills in animal training. They will have the ability to successfully execute clinical assessments, identify factors contributing to problem behaviours, and plan behaviour modification programmes, as well as other relevant professional skills such as effective communication and counselling skills. Graduates will also have the ability to design, execute, and interpret original research in this area in the dissertation paper.","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0923"},"WI0136":{"i":"WI0136","entryRequirements":"A New Zealand university entrance qualification or equivalent","strategicPurposeStatement":"This conjoint degree gives students the opportunity to complete the requirements of two Bachelors degrees over a reduced period of time. Graduates will have knowledge and skills from both law and arts disciplines which gives them a good grounding for careers in many areas. It is popular with students wishing to pursue careers in policy and research.","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0136"},"AK1232":{"i":"AK1232","entryRequirements":"A master's degree with a major in psychology.","strategicPurposeStatement":"PgDipCounsPsych graduates will have completed the necessary academic and practical preparation to become professional psychologists.","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1232"},"CN0284":{"i":"CN0284","entryRequirements":"An approved Bachelor's degree.  Shortlisted applicants will be invited to participate in interviews and other selection activities. All successful applicants will be required to meet the Children's Act 2014 safety checking requirements. These include police vetting, identity verification, and reference checks, undertaken in accordance with University policy and sector standards. A student for whom English is a second language must provide evidence of IELTS (Academic) 7.5 with no score less than 7.0 or equivalent. Applicants are required to disclose any criminal convictions; professional misconduct; and physical or mental health conditions that could affect their ability to practice safely. They must also meet any additional placement requirements for health-workforce students, such as immunisation, confidentiality agreements, and conduct expectations.","strategicPurposeStatement":"Graduates of the PGDipPsycAssist are prepared for safe, competent practice as registered Psychology Assistants. They are able to work effectively within mental health and addiction services, providing psychological assessment, psychoeducation, and interventions within the boundaries of the Psychology Assistant scope of practice as defined by the NZ Psychologists Board. Graduates integrate ethical, legal, Te Tiriti o Waitangi, cultural safety, and lived experience-informed considerations into psychological practice within their scope. They communicate effectively with individuals, whanau, groups, and interdisciplinary teams, and produce accurate, professional documentation. They use supervision effectively and engage in reflective practice to support their wellbeing and ongoing professional development. The programme equips graduates to work across diverse populations and contribute to recovery-oriented and trauma-informed services.","graduateProfile":"A range of assessments will be used including:  Structured role plays assessing engagement, cultural safety, ethical decision-making, psychological assessment and intervention skills. Written clinical documentation (e.g. case summaries, session notes) to demonstrating accuracy, clarity, and adherence to professional standards. Psychoeducation resources and video demonstrations assessing the ability to communicate psychological concepts safely and accessibly. Portfolio of practice including evidence from placement, recorded work samples, and supervisor feedback demonstrating competence across NZPB domains. Supervisor evaluations (clinical and cultural) and feedback from lived experience reflective practice facilitators. Reflective practice tasks (written or video), demonstrating self-awareness and integration of feedback. Assessment in the professional practice and practicum courses (PSYC493 and PSYC494) is pass/fail (competency-based) to ensure graduates meet the minimum standard for safe practice.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0284"},"AU4021":{"i":"AU4021","entryRequirements":"A graduate of the University of Auckland or a New Zealand university","strategicPurposeStatement":"LittD graduates will have made an original contribution of particular excellence to their field of study at an internationally recognised standard.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU4021"},"CN0325":{"i":"CN0325","entryRequirements":"An approved Bachelor's degree or equivalent","strategicPurposeStatement":"Students who qualify for the postgraduate certificate will have gained advanced knowledge and skills in international law and politics, enhanced employment options and an upgrade pathway for admission to the Master of Laws in International Law and Politics.","graduateProfile":"A range of assessments will be used including coursework, tests and formal examinations","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0325"},"AK1068":{"i":"AK1068","entryRequirements":"A bachelor's degree.","strategicPurposeStatement":"PgCertHumRights graduates will have advanced knowledge in human rights.  They will have well developed skills in critical thinking, problem solving, and communication and be prepared for further postgraduate study.","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1068"},"AU5785":{"i":"AU5785","entryRequirements":"Relevant bachelors degree and minimum GPA, or equivalent.","strategicPurposeStatement":"Graduates of the Juris Doctor will have attained the knowledge, skills, values, and professional attributes required to fulfil the academic stage of training to qualify for legal practice and the capabilities for further specialist postgraduate and/or research studies.","graduateProfile":"Combination of assignments, independent research, research essays, case reports, directed study, exams and online tests.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5785"},"WI0927":{"i":"WI0927","entryRequirements":"BSc or BSc (Tech) degree or equivalent. Those students who have an honours degree in a relevant field, may take 120 credits to complete the MEnvSci.","strategicPurposeStatement":"The Master of Environmental Sciences will distinguish itself by providing graduates with a combination of practical research skills and advanced theoretical knowledge and an understanding in environmental sciences but uniquely enhanced by cross disciplinary subject matter due to broader study in related subjects from other faculties (as appropriate).","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0927"},"AU5614":{"i":"AU5614","entryRequirements":"A New Zealand university entrance qualification or an approved alternative. Must meet entry requirements of each component degree. Selection criteria apply.","strategicPurposeStatement":"Graduates will demonstrate an advanced knowledge and comprehension of theory, applications and techniques in their chosen fields. They will demonstrate a capacity for independent research and application of knowledge and be able to analyse, synthesize, evaluate and report in a timely and professional manner.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5614"},"AU0246":{"i":"AU0246","entryRequirements":"Masters degree in Psychology","strategicPurposeStatement":"PGDipAppPsych graduates will meet the requirements for registration as psychologists under the Health Practitioners Competency Assurance Act. Graduates of the Organisational Psychology specialisation will have developed practical skills in applying organisational psychology techniques, such as job analyses, test validation, training needs analysis and evaluation, career counselling and development, organisation development and workplace well-being. Graduates with the Applied Behaviour Analysis (ABA) specialisation will have developed practical skills in applying behavioural principles with a wide variety of client groups, both child and adult, including those with intellectual and other disabilities, autism spectrum, and childhood-onset behavioural disorders. Graduates with the ABA specialisation also are eligible to sit the examination administered by the Behavior Analysis Certification Board for the internationally recognised credential of Board Certified Behavior Analyst (BCBA).","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU0246"},"AU5562":{"i":"AU5562","entryRequirements":"Admission to and successful completion of at least 30 points for the Master of Indigenous Studies. Further information is available from www.auckland.ac.nz","strategicPurposeStatement":"Graduates will have advanced knowledge and skills in indigenous development and research methodologies.","graduateProfile":"NA","educationPathway":"NA","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5562"},"OO0020":{"i":"OO0020","entryRequirements":"Honours degree in Psychology.  Candidates must be concurrently enrolled for a master's or doctoral degree in Psychology","strategicPurposeStatement":"This diploma provides advanced professional study and clinical training in Psychology.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0020"},"AU5781":{"i":"AU5781","entryRequirements":"A relevant Bachelors degree, and a minimum Grade Point Average (GPA).","strategicPurposeStatement":"Master of Behaviour Analysis graduates will know and understand the principles and tactics of the science of behaviour to improve quality of life for a range of clinical and non-clinical populations.","graduateProfile":"Assessments include coursework, assignments, projects, and thesis.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5781"},"OO0561":{"i":"OO0561","entryRequirements":"An Honours degree with an average grade of B+ or higher, or a publication record as a creative writer.","strategicPurposeStatement":"Graduates of the programme will be equipped with industry-standard knowledge and writing skills relevant to contemporary literature in Aotearoa New Zealand and internationally.","graduateProfile":"External assessment equivalent to thesis.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0561"},"AK1102":{"i":"AK1102","entryRequirements":"Bachelor's degree or equivalent.","strategicPurposeStatement":"PgDipAppPsych graduates will have a broad understanding of core psychological principles and evidence-based approaches to address practical challenges in diverse settings. They will be able to apply psychological tools and frameworks to support decision-making, wellbeing, and behaviour change. Graduates are prepared for further postgraduate study, including direct entry into the Master of Applied Psychology. They will be able to enhance their existing professional roles or seek new opportunities by integrating applied psychological knowledge and skills in roles requiring an understanding of human behaviour and motivation.?","graduateProfile":"Courses employ a diverse range of assessments, including case analyses, simulation-based interventions, reflective practice portfolios, collaborative presentations.","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1102"},"MY0425":{"i":"MY0425","entryRequirements":"A Postgraduate Diploma in Education (Counselling and Guidance), or a Postgraduate Diploma in Rehabilitation (Rehabilitation Counselling), or equivalent, with a minimum B average over all courses, and sufficient background of professional experience; a selection process applies.","strategicPurposeStatement":"Graduates will have acquired advanced professional counselling knowledge and capabilities.","graduateProfile":"Final examinations and research project","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0425"},"OO0505":{"i":"OO0505","entryRequirements":"A bachelor's degree or equivalent.","strategicPurposeStatement":"This programme provides chaplains with specialised training. Holders of the certificate will be able to demonstrate the ability to integrate thought and action, integrate professional and intellectual ability, exercise independent judgement, undertake analysis, research a topic, and reflect professionally upon one's own and others' actions.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0505"},"MY0373":{"i":"MY0373","entryRequirements":"Admission to the Master of Maori Studies requires that the candidate has: (b) been awarded or qualified for a relevant Bachelor degree or equivalent with at least a B grade average across 75 credits of the highest level specialisation courses; or? (c) been awarded or qualified for a relevant Postgraduate Diploma, or an equivalent qualification, with at least a B+ grade average across the 700-level courses for entry to the Research Pathway or a B grade average across the 700-level courses for entry to the Coursework Pathway.?","strategicPurposeStatement":"The goals of the Masters of Maori Studies are to equip graduates with a wide range of interdisciplinary and transdisciplinary skills and knowledge of contemporary te ao Maori that include a high level of fluency in te reo Maori me ona tikanga, matauranga Maori, and Te Tiriti o Waitangi. This is combined with an understanding, for example of Indigenous, political, social and economic conditions and solving real-world problems. Graduates will be equipped to engage independently and collaboratively in rigorous intellectual analysis, and critique of contemporary issues facing Tangata Whenua/ Tangata Tiriti, and bring novel solutions to local and global challenges.","graduateProfile":"The assessment arrangements for this programme seek to utilise best practice in terms of pedagogical effectiveness at postgraduate level and be aligned with Te Ao Maori. ?Assessment will be by a range of assignments through out the course.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0373"},"AK2015":{"i":"AK2015","entryRequirements":"A bachelor's degree with a B average or higher in papers in level 7 or equivalent.","strategicPurposeStatement":"Master of Gastronomy graduates will have advanced knowledge in gastronomy. They will be able to create new knowledge, critically evaluate information and communicate effectively, and be prepared for doctoral study or employment.","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK2015"},"CN0973":{"i":"CN0973","entryRequirements":"An approved Bachelor's degree or equivalent.","strategicPurposeStatement":"Graduates of the PGDipCBT will be able to:  (a) Demonstrate an appreciation of how colonisation and racism has contributed to poorer (mental) health outcomes in Maori  (b) Demonstrate an appreciation of how Maori models of wellbeing overlap and differ from western models of health  (c) Be aware of how to ethically set up a treatment frame to work with clients with mental health difficulties and how to adapt this for Maori in respect of contact and interviewing    (d) Demonstrate knowledge of CBT formulation skills to conceptualise complex mental health presentations  (e) Demonstrate knowledge of specific mental health problems and presentations  (f) Demonstrate knowledge of how western CBT needs to be adapted to be relevant for Maori  (g) Demonstrate knowledge of how CBT can provided in group settings to deliver cost and time efficiencies in health services.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0973"},"VI00K4":{"i":"VI00K4","entryRequirements":"New Zealand Bachelor's degree and two years of relevant work experience or extensive practical, professional or scholarly experience.","strategicPurposeStatement":"Graduates will have gained an improved understanding of public policy analysis and public sector management issues, as well as the opportunity to extend their technical or managerial skills.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI00K4"},"MY0442":{"i":"MY0442","entryRequirements":"Completion of both an undergraduate degree with a major in Psychology AND a Masters or Doctoral degree in Psychology and; Completion of three prerequisite papers or their accepted equivalents at 700-level within the previous three years to at least B+ level and; Being selected by a panel for admission to clinical training.","strategicPurposeStatement":"At the successful conclusion of the MClinPsych, graduates will satisfy the clinical examiners that they have a detailed knowledge of the theory, methodology, models and empirical status of clinical psychology. They will be eligible for registration as a psychologist under the clinical scope with the New Zealand Psychologists Board under the HPCA Act (2003).","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0442"},"CN0196":{"i":"CN0196","entryRequirements":"Applicants need to have a Bachelor's degree with a major or equivalent in Te Reo Maori.","strategicPurposeStatement":"Graduates will have an advanced knowledge of the language, linguistic competence, some in-depth knowledge about contemporary and /or historical aspects of the language, advanced skills for research and have completed an original research project.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0196"},"WI1024":{"i":"WI1024","entryRequirements":"Bachelors degree or equivalent, completed at a specified minimum level of attainment.","strategicPurposeStatement":"Graduates of the Master of Professional Practice in Social and Community Services will be well prepared for further postgraduate studies in social work, health and other related areas or be well placed to respond to the needs of the community.","graduateProfile":"Examination or internal assessment.","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI1024"},"MY0359":{"i":"MY0359","strategicPurposeStatement":"Graduates of the Massey University Master of Applied Linguistics will be able to critically analyse major issues and themes in Applied Linguistics using sound theoretical knowledge and a high-level of skill in analysis, synthesis and critical evaluation of language issues and their implications. They will be able to contribute to research and practice relating to second language acquisition and language use in a range of research and educational contexts in New Zealand and abroad.","graduateProfile":"Graduates of the Massey University Master of Applied Linguistics will be able to critically analyse major issues and themes in Applied Linguistics using sound theoretical knowledge and a high-level of skill in analysis, synthesis and critical evaluation of language issues and their implications. They will be able to contribute to research and practice relating to second language acquisition and language use in a range of research and educational contexts in New Zealand and abroad.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0359"},"CN0114":{"i":"CN0114","entryRequirements":"An approved Bachelor's degree.","strategicPurposeStatement":"Graduates will have an advanced level of knowledge in their discipline or area of specialisation developed over a full year of study or equivalent.  They will have an advanced knowledge of theoretically sophisticated subject matter in their discipline or area of specialization and have developed the ability to critically evaluate the academic literature in their discipline or area of specialization. They will be able to synthesize information and communicate their findings in both oral and written form.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0114"},"AU5613":{"i":"AU5613","entryRequirements":"A New Zealand university entrance qualification or an approved alternative. Must meet entry requirements of each component degree. Selection criteria apply.","strategicPurposeStatement":"Graduates will demonstrate an advanced knowledge and comprehension of theory, applications and techniques in their chosen fields. They will demonstrate a capacity for independent research and application of knowledge and be able to analyse, synthesize, evaluate and report in a timely and professional manner.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5613"},"CN0336":{"i":"CN0336","entryRequirements":"An approved Bachelor's degree.","strategicPurposeStatement":"Students will have acquired an advanced understanding of the theories of the causes of crime, including psychological, sociological, cultural and environmental theories and the empirical research that underpins those theories. They will also have an understanding of the statute and case law governing the criminal justice process, particularly aspects of the criminal law, criminal procedure and sentencing. They will have a good knowledge of the systems and institutions involved in the criminal justice process including prisons and providers of community service penalties, the police, the courts, restorative justice and health providers whose activities are linked to the criminal justice process.  Graduates will be able to interpret relevant legislation, analyse and critique existing policies in criminal justice fields and identify or appraise suggestions for reform.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0336"},"LIO593":{"i":"LIO593","entryRequirements":"A relevant bachelors degree.","strategicPurposeStatement":"Graduates of this programme will gain an advanced understanding of managing parks, natural resource recreation, community recreation outdoor leadership or tourism management.","developedBy":"Lincoln University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=LIO593"},"CN0326":{"i":"CN0326","entryRequirements":"Bachelor of Laws.","strategicPurposeStatement":"Graduates of this degree will have extended knowledge and skills in law and politics and well-developed research skills. The degree prepares students for careers in the diplomatic service, specialised legal practice, inter-governmental agencies, non-governmental organisations and the military, or for doctoral study.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0326"},"OO0506":{"i":"OO0506","entryRequirements":"A bachelor's degree or equivalent.","strategicPurposeStatement":"This programme provides chaplains with specialised training. Holders of the diploma will be able to demonstrate the ability to integrate thought and action, integrate professional and intellectual ability, exercise independent judgement, undertake analysis, research a topic, and reflect professionally upon one's own and others' actions.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0506"},"MY0414":{"i":"MY0414","entryRequirements":"A relevant bachelors degree with grades which meet College and University requirements for admission to advanced degrees.","strategicPurposeStatement":"Graduates will demonstrate (1) knowledge in social work theory and practice; (2) competency in practice in applied settings, (3) ability to work independently, (4) ability to communicate effectively both orally and in writing, (5) advanced analytical skills.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0414"},"AK1050":{"i":"AK1050","entryRequirements":"(a) a Bachelor of Laws or (b) a Bachelor of Laws (Honours) or equivalent","strategicPurposeStatement":"The programme is aimed at those who have already completed a law degree and wish to gain advanced legal knowledge and develop their research skills in areas of law relating to crime, finance, banking, taxation, intellectual property, corporate governance, securities, competition, employment, property and resource management.","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1050"},"CN0295":{"i":"CN0295","entryRequirements":"Extensive practical, professional or scholarly experience of an appropriate kind, high proficiency in English, and approval of the Executive Dean of Science.","strategicPurposeStatement":"Successful completion of the Postgraduate Certificate in Organisational Psychology will enable learners to apply for the Master in Organisational Psychology degree which supports graduates to be ready to work as professionals with specific organisational psychology knowledge and skills within a range of organisations, using research, evidence-based and scientific procedures, and methods to support achievement of organisational goals.","graduateProfile":"A range of assessments will be used including written assignments, quizzes, forum discussions, presentations, reflective journals, research proposals, project reports.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0295"},"AU5001":{"i":"AU5001","entryRequirements":"A four year Bachelors degree, or a Bachelors (Honours) degree, or a Bachelors degree with additional requirements.  Individual specialisations have specific requirements.","strategicPurposeStatement":"MProfStuds graduates will have developed an ability to critically analyse and reflect upon the theoretical and practical issues informing their chosen field of study.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5001"},"CN0185":{"i":"CN0185","entryRequirements":"An approved Bachelor's degree plus professional experience","strategicPurposeStatement":"Holders of the postgraduate certificate will have engaged in the critical analysis of models of indigenous development at an advanced level and will have a basis for further postgraduate study.","graduateProfile":"NA","educationPathway":"NA","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0185"},"CN1186":{"i":"CN1186","entryRequirements":"An approved Bachelor's degree and relevant professional experience.","strategicPurposeStatement":"Graduates from the Master of Systems Change will have the appropriate attitudes, skills and knowledge to be employed professionally in government, philanthropic, and social sectors and to enact changes within these sectors.   They will be knowledgeable and skilled in analysing systems and seeing opportunities for change within them. They will be able to create innovative and principled solutions that enact change and will be able to apply these to their area of work.  They will be able to learn independently and communicate effectively.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN1186"},"AK1069":{"i":"AK1069","entryRequirements":"A bachelor's degree.","strategicPurposeStatement":"PgDipHumRights graduates will have advanced knowledge and understanding of human rights. They will be able to engage in research in the area, taking an analytical, critical and reflective approach and be prepared for further postgraduate study.","developedBy":"Auckland University of Technology","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AK1069"},"AU5556":{"i":"AU5556","entryRequirements":"A New Zealand university entrance qualification or an approved alternative. Selection is based on results from Parts I and II of the LLB, and the evaluation of supplementary material related to the selected music major.","strategicPurposeStatement":"Graduates will demonstrate knowledge and understanding of the content and application of elements of both Music and Law disciplines with additional enhanced research and writing skills within the law component.","graduateProfile":"NA","educationPathway":"NA","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU5556"},"AU0482":{"i":"AU0482","entryRequirements":"Bachelor's degree or equivalent qualification.","strategicPurposeStatement":"PGDipArts graduates will have advanced knowledge and understanding of the content and the discipline of a subject or specialization in the Faculty of Arts. They will be able to engage in research in the area taking an analytical, critical and reflective approach.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU0482"},"CN0794":{"i":"CN0794","entryRequirements":"Bachelor of Arts or Bachelor of Fine Arts or appropriate and extensive practical, professional or scholarly experience.","strategicPurposeStatement":"Graduates of this qualification will have a deep knowledge and understanding of the theory and practice of art curatorship. They will have completed professional training for curators and for related roles in public art museums and private galleries.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0794"},"WI0673":{"i":"WI0673","entryRequirements":"Bachelors degree or equivalent and a counselling qualification and at least five years' full-time equivalent experience in counselling.","strategicPurposeStatement":"Graduates will have skills, ideas and attributes to conduct constructive professional conversations in particular practice domains.  The specialist programmes, Counselling Supervision and Family Counselling, are designed to offer postgraduate students who are experienced counselling practitioners, advanced education for professional practice and accreditation.","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0673"},"WI0926":{"i":"WI0926","entryRequirements":"BA, BSocSc or BEP degree or equivalent. Those students who have an honours degree in a relevant field, may take 120 credits to complete the MEnvSoc.","strategicPurposeStatement":"The Master of Environment and Society is distinctive because it provides graduates with a combination of practice-based research skills and advanced theoretical knowledge and an understanding of environment-society relations grounded in the social sciences, but enhanced by inter-disciplinary papers from related subjects.","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0926"},"CN0956":{"i":"CN0956","entryRequirements":"Bachelor's degree including specified prerequisites plus practical professional experience.","strategicPurposeStatement":"Master of Counselling graduates will practise with a high level of competence in a diverse range of professional environments, using theory and research to inform their current and future practice. They will contribute to the counselling profession and the wider community through effective, highly skilled and ethically based practice. They will also make an effective contribution to the research environment by engaging in counselling-related research activity.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0956"},"VI005I":{"i":"VI005I","entryRequirements":"The PGCertLing includes a core course on methodology in linguistic research, including training in quantitative and qualitative methods. Students then take one further course which covers an advanced topic in linguistics, and includes the opportunity to carry out a small-scale research project or a full research proposal. \n\n\n\r\nAssessments include reports demonstrating methodological techniques, scaffolded assessment towards a research project or proposal (e.g. annotated bibliography, literature review, final report) and oral seminar presentations","strategicPurposeStatement":"Students in the Postgraduate Certificate of Linguistics will be part of the research culture of the Linguistics programme within the School of Linguistics and Applied Language Studies. The PGCertLing degree will prepare graduates who:  *       have specialised knowledge of at least one current area of linguistic research  *       have a grounding in the use of quantitative and qualitative methods for collecting and analysing linguistic data  *       are able to make critically informed decisions about the methods appropriate for investigating different research questions  *       are progessing towards being able to develop their own complex ideas related to linguistic structure and language use based on a sound understanding of relevant research  *       communicate effectively and accurately about linguistic research in different contexts and through different media  *       demonstrate intellectual integrity and an understanding of the ethics of scholarship.    With these attributes, developed in the formal curriculum and tested through academic assessment, graduates will be building towards having the knowledge, skills and experience to undertake independent advanced research in linguistics.  In the programme students will develop some high-level transferable skills for language-related fields, including language and social policy, marketing, and speech technology.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI005I"},"VI002W":{"i":"VI002W","strategicPurposeStatement":"Graduates will have a strong theoretical and practical background in current museum and heritage practice. They will also have specialised knowledge in fields such as exhibition studies, Maori museum practice, or historic heritage practice, which will enhance their career prospects in the museum and heritage sector. Graduates may be able to continue to the Master of Museum and Heritage Practice (VI002T).","graduateProfile":"NA","educationPathway":"NA","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI002W"},"MY0738":{"i":"MY0738","entryRequirements":"(a) meet the University admission requirements as specified, and  (b) have been awarded or qualified for a relevant Bachelor's degree, or equivalent.","strategicPurposeStatement":"Diplomates will demonstrate evaluative thinking in a range of applied policy and organisational contexts, identify and understand key concepts, theories, approaches and methods of evaluation research. They will identify evaluation research questions and design appropriate evaluations across a range of settings.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0738"},"CN0134":{"i":"CN0134","entryRequirements":"A bachelor's degree with Honours or masters degree or doctorate in psychology and passes in specified qualifying courses.","strategicPurposeStatement":"Graduates are trained as competent clinical psychologists who can apply general conceptual and technical skills in diverse professional settings. Graduates will understand the interactive and mutually informative relationships between science and practice. The programme provides a comprehensive integration of academic and practical work to produce graduates who adapt to societal needs and changes in service delivery, think critically and communicate clearly. In addition, graduates contribute to the knowledge base of psychology through research, evaluate the effectiveness of professional services, embrace standards of professional ethics, recognise the importance of personal values, and appreciate and respect individual and cultural differences. Graduates may work as professional clinicians or undertake doctoral study to become specialists in an area of practice or pursue a career in research.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0134"},"WI0061":{"i":"WI0061","entryRequirements":"Masters or Honours degree with at least second class honours(first division) or distinction, or equivalent.","graduateProfile":"Graduates will have an advanced knowledge in a specific discipline. They will be able to critically evaluate information, communicate effectively and present scholarly publishable work. They will be prepared for doctoral studies.","developedBy":"University of Waikato","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=WI0061"},"CN0156":{"i":"CN0156","entryRequirements":"An approved Bachelor's degree.","strategicPurposeStatement":"Graduates will have advanced knowledge and understanding of current research in linguistics. They will have the skills necessary to understand how linguistic systems operate and to approach the connections between a language system and its social context. They will have carried out a substantial piece of independent research so they will have expertise in the formulation of research questions, data collection, statistical analysis and hypothesis testing. Graduates will also be excellent communicators having been trained to produce cogent and well-structured research reports.","developedBy":"University of Canterbury","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=CN0156"},"MY0371":{"i":"MY0371","strategicPurposeStatement":"Graduates will have advanced knowledge in a specific humanities or social sciences discipline, will be able to apply this knowledge in relevant contexts, and will be competent independent researchers.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0371"},"VI0015":{"i":"VI0015","entryRequirements":"Admission is by invitation to students who have completed the second year of the LLB.","strategicPurposeStatement":"In addition to the attributes displayed by graduates with an LLB, graduates of an LLB(Hons) will have refined legal research, writing and analytical skills.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI0015"},"MY0269":{"i":"MY0269","entryRequirements":"A relevant bachelor's degree.","strategicPurposeStatement":"Holders will have advanced knowledge in a specific humanities and social sciences discipline and be able to apply this knowledge in relevant contexts.","developedBy":"Massey University","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=MY0269"},"OO0565":{"i":"OO0565","entryRequirements":"Bachelor's degree in Psychology or approved equivalent, with B+ average in year 3.","strategicPurposeStatement":"Graduates of this programme will be competent to practise under supervision, safely, and effectively in clinical settings.","graduateProfile":"Internal assessment, examinations","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0565"},"AU0355":{"i":"AU0355","entryRequirements":"Parts 1 and 2 of the Bachelor of Laws. LLB graduates are not permitted to enrol.","strategicPurposeStatement":"LLB(Hons) graduates are able to practise law or work in related fields requiring analytical skills, research skills, communication skills, social appreciation, public responsibility and knowledge of the law and its applications. They will have enhanced legal writing and research skills.","developedBy":"University of Auckland","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=AU0355"},"OO0417":{"i":"OO0417","entryRequirements":"A 4 year Bachelor's degree; or a 3 year Bachelor's degree and 3 years relevant experience; or equivalent","strategicPurposeStatement":"This degree provides in-depth study, research and training in indigenous studies. It provides advanced knowledge in the field and the ability to study independently and carry out original research.","developedBy":"University of Otago","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=OO0417"},"VI0093":{"i":"VI0093","entryRequirements":"a degree of Victoria University of Wellington awarded at least 5 years prior to candidature; or other acceptable preparation.","strategicPurposeStatement":"A specialist law degree intended to recognise major achievements in a field of law.","developedBy":"Victoria University of Wellington","qualityAssuredBy":"Committee on University Academic Programmes","nzqaLink":"https://www.nzqa.govt.nz/nzqf/search/viewQualification.do?selectedItemKey=VI0093"}};
